/** Why the main process broadcast a new workspace context state. */
export const WORKSPACE_CONTEXT_CHANGE_REASONS = [
  'switch',
  'account-change',
  'departed',
  'organizations',
] as const;
export type WorkspaceContextChangeReason =
  (typeof WORKSPACE_CONTEXT_CHANGE_REASONS)[number];

export function isWorkspaceContextChangeReason(
  value: unknown,
): value is WorkspaceContextChangeReason {
  return (
    typeof value === 'string' &&
    WORKSPACE_CONTEXT_CHANGE_REASONS.some((reason) => reason === value)
  );
}

/**
 * `workspace-context:changed` payload: the full state plus the reason, so the
 * renderer can distinguish a deliberate switch (which starts a new Active-from
 * epoch) from a fallback it should explain (`departed`) or a silent membership
 * refresh (`organizations`).
 */
export interface WorkspaceContextBroadcast extends WorkspaceContextState {
  reason: WorkspaceContextChangeReason;
}

export interface SetWorkspaceContextRequest {
  context: WorkspaceContext;
  /**
   * The revision the caller last observed. When supplied and stale, main
   * rejects the switch instead of letting a second window silently win.
   */
  expectedRevision?: number;
}

/** Transcript reference previews read through main's provider connections. */
export interface ReferencePreviewApi {
  linearScope(): Promise<LinearPreviewScope>;
  linearTeams(): Promise<LinearTeamKeysResult>;
  linearIssue(
    request: LinearIssuePreviewRequest,
  ): Promise<LinearIssuePreviewResult>;
  githubScope(): Promise<GitHubPreviewScope>;
  githubOrigin(origin: GitHubReferenceOrigin): Promise<GitHubOriginRepository>;
  github(target: GitHubPreviewTarget): Promise<GitHubPreviewResult>;
}

/** Preload surface for the Personal/organization context (CAN-2952). */
export interface WorkspaceContextApi {
  get(): Promise<WorkspaceContextState>;
  set(request: SetWorkspaceContextRequest): Promise<WorkspaceContextState>;
  onChanged(callback: (state: WorkspaceContextBroadcast) => void): () => void;
}

/**
 * Why a cached catalog may be stale (CAN-2955). `unavailable` means the
 * server does not advertise `org-projects-v1` (or nothing is signed in);
 * `offline` means the last refresh failed to reach the server;
 * `access-changed` means the server refused the context (membership lost).
 */
export type OrgProjectCatalogError =
  | 'unavailable'
  | 'offline'
  | 'access-changed';

/** The desktop's cached catalog for one context: the shared snapshot plus freshness. */
export interface DesktopOrgProjectCatalogSnapshot extends OrgProjectCatalogSnapshot {
  /** True when the projects come from the cache and the last refresh failed. */
  stale: boolean;
  error: OrgProjectCatalogError | null;
  /**
   * Set by a refresh that also asked the server to re-read the organization's
   * repositories from GitHub (CAN-3489). `failed` means that re-read failed or
   * ran past its time box: the catalog itself is current, but may miss new
   * repositories. `not-connected` means the server confirmed no active GitHub
   * connection. Transient and never persisted; absence does not prove a
   * connection exists (older servers and unsupported capabilities omit it).
   */
  repositoriesRefresh?: 'failed' | 'not-connected';
}

export interface OrgProjectsListRequest {
  context: WorkspaceContext;
}

export interface OrgProjectsRefreshRequest {
  context: WorkspaceContext;
  force?: boolean;
  /**
   * First ask the server to re-read the organization's repositories from
   * GitHub, then fetch unconditionally (CAN-3489). Ignored for Personal.
   */
  repositories?: boolean;
}

export interface OrgProjectsSetPreferenceRequest {
  context: WorkspaceContext;
  projectId: string;
  preference: OrgProjectPreference;
}

/** Device-private only: excluded from cloud, Portal and telemetry contracts. */
export interface OrgProjectRelationship {
  projectId: string;
  personalWorkspaceId: string;
}
export type OrgProjectLinksUnknownReason =
  | 'catalog-unavailable'
  | 'context-changed'
  | 'credentials-unavailable'
  | 'inventory-unavailable'
  | 'remote-unavailable';
export type OrgProjectLinksListResult =
  | { status: 'resolved'; links: OrgProjectRelationship[] }
  | { status: 'unknown'; reason: OrgProjectLinksUnknownReason };
export interface OrgProjectLinksDecideRequest extends OrgProjectRelationship {
  decision: 'dismiss' | 'view';
}

/**
 * Preload surface for reading a work scope's Agent Ledger (the Ledger panel).
 * Every read resolves: failures arrive as `LedgerViewResult` errors.
 */
export interface LedgerApi {
  searchEntries(
    request: LedgerViewSearchRequest,
  ): Promise<LedgerViewResult<LedgerEntriesSearchResult>>;
  getEntry(
    request: LedgerViewEntryRequest,
  ): Promise<LedgerViewResult<LedgerViewEntry>>;
  /** Adds an entry as the person using the panel. */
  addEntry(
    request: LedgerViewAddRequest,
  ): Promise<LedgerViewResult<LedgerViewReceipt>>;
  /** Changes an entry's status or owner as the person using the panel. */
  updateEntry(
    request: LedgerViewUpdateRequest,
  ): Promise<LedgerViewResult<LedgerViewReceipt>>;
  /** One page of the owners the person may assign. */
  listOwners(
    request: LedgerViewOwnersRequest,
  ): Promise<LedgerViewResult<LedgerViewOwnerPage>>;
  /** Committed changes, coalesced by main. */
  onEntriesChanged(
    callback: (event: LedgerViewChangedEvent) => void,
  ): () => void;
  /** One page of the global Feed. */
  searchFeed(
    request: LedgerFeedRequest,
  ): Promise<LedgerViewResult<LedgerFeedPage>>;
  /** A Feed row of another device or a teammate, read only. */
  getFeedEntry(
    request: LedgerFeedEntryRequest,
  ): Promise<LedgerViewResult<LedgerViewEntry>>;
  /** This device's operations and top-level tasks, with their rollups. */
  listFeedWork(
    request: LedgerFeedWorkRequest,
  ): Promise<LedgerViewResult<LedgerFeedWorkPage>>;
}

/**
 * Preload surface for reading a work scope's observed cost (the Cost panel,
 * the Session breakdown, a pipeline run's cost and the usage popover). Every
 * read resolves: failures arrive as `CostViewResult` errors.
 */
export interface CostApi {
  getScope(request: CostScopeRequest): Promise<CostViewResult<CostScopeView>>;
  getChat(request: CostChatRequest): Promise<CostViewResult<CostChatView>>;
  getPipelineRun(
    request: CostPipelineRunRequest,
  ): Promise<CostViewResult<PipelineRunCostView>>;
  refresh(
    request: CostRefreshRequest,
  ): Promise<CostViewResult<CostRefreshReceipt>>;
  /**
   * Marks a scope as on screen in this window until the returned function is
   * called, so main refreshes it shortly after work in it finishes.
   */
  watchScope(scope: CostScopeRef): () => void;
  /** Stored figures changed. Carries scope refs and a revision only. */
  onUpdated(callback: (event: CostUpdatedEvent) => void): () => void;
}

/**
 * Bind an existing Personal checkout to the organization project for the same
 * repository (CAN-3415). Nothing on disk moves; only ownership changes.
 */
export interface OrgProjectConvertWorkspaceRequest {
  workspaceId: string;
  organizationId: string;
  projectId: string;
}
/**
 * Convert a Personal multi-repo project, including temporary combinations,
 * in place (CAN-3532). The definition contains only repositories held by usable
 * organization projects, in local order. At least one held repository is
 * required except for member-created empty projects. Retries reuse the member's
 * private definition. Automatic selection checks all member organizations;
 * Add project and newly gained settings repositories remain strict.
 */
export interface OrgProjectConvertMultiRepoWorkspaceRequest {
  workspaceId: string;
  organizationId: string;
}
/**
 * Convert a Personal Cowork project in place to a new private Cowork project
 * of the organization. Default Chats spaces never convert.
 */
export interface OrgProjectConvertCoworkWorkspaceRequest {
  workspaceId: string;
  organizationId: string;
}
/**
 * Move a Personal project, with every worktree in it, to one of the member's
 * organizations. The member picks the organization explicitly; the selected
 * workspace context does not change.
 */
export interface OrgProjectMoveRequest {
  workspaceId: string;
  organizationId: string;
}
export type OrgProjectMoveResult =
  | {
      ok: true;
      workspaceId: string;
      organizationId: string;
      /** The organization project the workspace is now bound to. */
      projectId: string;
    }
  | {
      ok: false;
      code: OrgProjectMoveErrorCode;
      /** The organization project created before the move failed, when one was. */
      organizationProjectId?: string;
    };
/** Return a converted workspace to its recorded Personal owner (CAN-3415). */
export interface OrgProjectMoveBackToPersonalRequest {
  workspaceId: string;
}
/**
 * Why a conversion was refused. Every refusal leaves the workspace exactly as
 * it was: a conversion either completes or is rolled back to Personal.
 */
export type OrgProjectConversionErrorCode =
  /** The organization-projects flag or the `org-projects-v1` capability is off, or no account is signed in. */
  | 'disabled'
  | 'workspace-not-found'
  | 'workspace-unreadable'
  /**
   * A default Chats space, a multi-repo workspace with no repositories, or a
   * workspace of another conversion's type (single-repo, multi-repo, and
   * Cowork projects convert through their own operations).
   */
  | 'unsupported-workspace'
  /** The workspace already has an organization owner. */
  | 'not-personal'
  /** Not in the organization catalog, not active, not usable by this member, or not a local code project. */
  | 'project-unavailable'
  /** Another workspace on this device is already bound to the project. */
  | 'project-already-bound'
  /**
   * The checkout's repository is not the organization project's repository,
   * or a multi-repo project has a repository no project of the organization
   * holds (CAN-3532).
   */
  | 'repository-mismatch'
  /** The member reached the cap on private organization projects (CAN-3532). */
  | 'member-project-limit'
  /** The checkout's Git remote could not be read. */
  | 'repository-unavailable'
  /** A setup, conversion, or move back of this project or workspace is running. */
  | 'busy'
  | 'offline'
  /** The organization refused or lost the claim; the workspace stayed Personal. */
  | 'conversion-failed'
  /**
   * Automatic conversion only (CAN-3416): the workspace already carries an
   * `ownershipTransfer`, so it was converted once and moved back to Personal.
   * Automatic conversion never converts it again; an explicit one may.
   */
  | 'previously-converted';
export type OrgProjectMoveBackErrorCode =
  | 'workspace-not-found'
  | 'workspace-unreadable'
  /** The workspace has no conversion to undo. */
  | 'not-converted'
  | 'busy'
  /** The organization instance could not be released; nothing changed. */
  | 'release-failed'
  /** The moved activity could not be returned to Personal (CAN-3418); nothing changed. */
  | 'activity-return-failed';
export type OrgProjectConversionResult =
  | {
      ok: true;
      workspaceId: string;
      owner: WorkspaceOwnerBinding;
      ownershipTransfer: WorkspaceOwnershipTransfer;
    }
  | {
      ok: false;
      code: OrgProjectConversionErrorCode;
      /**
       * A Cowork conversion's organization project, when one was created
       * before the failure. It stays unbound; a retry of the same project
       * under the same name reuses it.
       */
      organizationProjectId?: string;
    };
export type OrgProjectMoveBackResult =
  | {
      ok: true;
      workspaceId: string;
      ownershipTransfer: WorkspaceOwnershipTransfer;
    }
  | { ok: false; code: OrgProjectMoveBackErrorCode };
/** Broadcast after a conversion or a move back changed a workspace's owner. */
export interface OrgProjectOwnershipChangedEvent {
  workspaceId: string;
  organizationId: string;
  projectId: string;
  owner: 'organization' | 'personal';
}

/**
 * Why a folder cannot become a member's organization project (CAN-3534). Every
 * refusal is decided before any server call and leaves the folder untouched.
 */
export type OrgMemberFolderRefusalReason =
  /** A subfolder of a repository, not its top-level folder. */
  | 'inside-repo'
  /** A linked git worktree, not the repository's main checkout. */
  | 'linked-worktree'
  /** The folder's project manifest lists more than one repository. */
  | 'multi-repo'
  /** The folder is already bound to an organization project. */
  | 'already-org-project'
  /** The folder is inside another project, or contains one. */
  | 'overlaps-project'
  /** The organization has a project for this repository the member cannot use. */
  | 'no-access'
  /** More than one organization project matches this repository. */
  | 'ambiguous'
  /** The folder or its git remote could not be read. */
  | 'unreadable'
  /**
   * A multi-repo project has a repository that is not one of the
   * organization's projects (CAN-3546); `repositories` names them.
   */
  | 'outside-organization';

/** The GitHub repository a folder's origin points at. */
export interface OrgMemberFolderRepository {
  host: 'github.com';
  owner: string;
  name: string;
}

export interface InspectOrgMemberFolderRequest {
  organizationId: string;
  path: string;
}

/**
 * Which of the member's organizations holds a repository the Add project
 * dialog is about to add (the hybrid model's create-time nudge): a folder by
 * its absolute path, or a clone URL. Exactly one of the two.
 */
export type OrgRepositoryOwnerRequest =
  | { path: string; remoteUrl?: undefined }
  | { remoteUrl: string; path?: undefined };

/**
 * What Create new makes from a chosen folder (CAN-3534). The folder decides
 * the kind: a plain folder is Cowork, a top-level git folder is Code.
 */
export type OrgMemberFolderInspection =
  | { kind: 'cowork' }
  | {
      kind: 'code';
      /** `new` makes a private project; otherwise the folder is linked to this organization project. */
      target: 'new' | { projectId: string; projectName: string };
      /** `null` when the folder has no origin, or one outside GitHub. */
      repository: OrgMemberFolderRepository | null;
      /** The Personal project already on this folder, which moves to the organization. */
      personalWorkspaceId?: string;
    }
  /**
   * A multi-repo project folder, or a Personal multi-repo project's root,
   * whose repositories are all the organization's projects (CAN-3546).
   */
  | {
      kind: 'multi-repo';
      repositoryCount: number;
      /** The Personal multi-repo project on this folder, which moves to the organization. */
      personalWorkspaceId?: string;
    }
  | {
      kind: 'refused';
      reason: OrgMemberFolderRefusalReason;
      /** For `outside-organization`: the repositories the organization does not hold. */
      repositories?: string[];
    };

export interface CreateOrgMemberCodeProjectRequest {
  creationKey?: string;
  organizationId: string;
  name: string;
  /** Applies only when creating a new organization definition. */
  privateMemory?: boolean;
  /** Existing git folder to bind in place. Omit to start a new repository. */
  folderPath?: string;
  /** Existing server definition to resume after local setup failed. */
  organizationProjectId?: string;
}

export type CreateOrgMemberCodeProjectResult =
  | { ok: true; organizationProjectId: string; localWorkspaceId: string }
  | {
      ok: false;
      code: 'unavailable' | 'create-failed' | 'limit-reached';
      organizationProjectId?: string;
    }
  /** The folder was refused when it was inspected again at create time. */
  | { ok: false; code: 'refused'; reason: OrgMemberFolderRefusalReason }
  | {
      ok: false;
      code: 'setup-failed';
      organizationProjectId: string;
      /** Why the in-place conversion of an existing folder was refused. */
      conversionCode?: OrgProjectConversionErrorCode;
    };

/**
 * Create a member's multi-repo organization project from Add project
 * (CAN-3546): an empty one whose settings then add its repositories (Create
 * new), or one from a multi-repo project folder (Existing folder).
 */
export interface CreateOrgMemberMultiRepoProjectRequest {
  organizationId: string;
  name: string;
  /** Applies only when creating a new organization definition. */
  privateMemory?: boolean;
  /** Existing folder: a multi-repo project folder or a Personal multi-repo project's root. */
  folderPath?: string;
  /** The local project a failed setup already made; resuming never makes another. */
  localWorkspaceId?: string;
}

export type CreateOrgMemberMultiRepoProjectResult =
  | { ok: true; organizationProjectId: string; localWorkspaceId: string }
  | { ok: false; code: 'unavailable' | 'create-failed' | 'limit-reached' }
  /** Nothing was created: the folder or one of its repositories was refused. */
  | {
      ok: false;
      code: 'refused';
      reason: OrgMemberFolderRefusalReason;
      repositories?: string[];
    }
  /** The local project exists but is not bound yet; retry with its id. */
  | {
      ok: false;
      code: 'setup-failed';
      localWorkspaceId: string;
      /** Why the in-place conversion of the local project was refused. */
      conversionCode?: OrgProjectConversionErrorCode;
    };

/**
 * Check, before anything is staged, which repositories an organization's
 * multi-repo project can take (CAN-3546). The project's settings disable the
 * ones it cannot; adding one is still refused by the add itself.
 */
export interface OrgMultiRepoRepositoryCheckRequest {
  workspaceId: string;
  /** Local checkouts, by absolute path. */
  repoPaths?: string[];
  /** Clone URLs not cloned yet. */
  remoteUrls?: string[];
}

/**
 * `outside`: the organization does not hold the repository. `neutral`: it
 * has no remote, so it is never refused (CAN-3544).
 */
export type OrgMultiRepoRepositoryEligibility =
  | 'eligible'
  | 'outside'
  | 'neutral';

export type OrgMultiRepoRepositoryCheckResult =
  /** Not an organization's multi-repo project: nothing is refused. */
  | { kind: 'not-organization' }
  | {
      kind: 'checked';
      organizationName: string;
      /**
       * Keyed by the requested path or URL. A path whose remote Git could not
       * read is absent; adding it reports that.
       */
      repositories: Record<string, OrgMultiRepoRepositoryEligibility>;
    }
  /** The organization's projects could not be read; `message` says so. */
  | { kind: 'failed'; message: string };

/** Bind a folder in place to an organization project that has no GitHub repository. */
export interface OrgProjectSetupFromFolderRequest {
  projectId: string;
  path: string;
}

/** Preload surface for the organization project catalog (CAN-2955). */
/**
 * Promote the Personal organization into a team in place (CAN-3706), invite
 * into an organization, and bring explicitly selected Personal projects.
 * Main validates every request and reply.
 */
export interface PersonalOrganizationUpgradeApi {
  inviteStatus(request: {
    organizationId: string;
    email: string;
  }): Promise<OrganizationInviteStatus | OrganizationOperationRefusal>;
  promote(
    request: UpgradePersonalOrganizationRequest,
  ): Promise<
    PersonalOrganizationPromotionOutcome | OrganizationOperationRefusal
  >;
  invite(request: {
    organizationId: string;
    invite: SendOrganizationInviteRequest;
  }): Promise<OrganizationInviteResult | OrganizationOperationRefusal>;
  listProjects(): Promise<{ projects: PersonalProject[] }>;
  convert(
    request: PersonalProjectConversionRequest,
  ): Promise<PersonalProjectOperation>;
  status(request: {
    operationId: string;
  }): Promise<PersonalProjectOperation | null>;
}

/** Result envelope for hosted settings IPC; errors cross as plain data. */
export type AccountOrganizationSettingsResponse =
  | { ok: true; result: unknown }
  | { ok: false; error: SettingsErrorPayload };

/**
 * Hosted account and organization settings (desktop bridge). The renderer
 * names a fixed `SETTINGS_OPERATIONS` entry and its input; main re-validates
 * the name and input, executes the call in an isolated hosted session for the
 * asserted account, and validates the result. The renderer never chooses a
 * URL, method, header, identity, or upload target.
 */
export interface AccountOrganizationSettingsApi {
  read(request: {
    accountId: string;
    operation: string;
    input: unknown;
  }): Promise<AccountOrganizationSettingsResponse>;
  write(request: {
    accountId: string;
    operation: string;
    input: unknown;
  }): Promise<AccountOrganizationSettingsResponse>;
  /** Start a stream bound to the calling window; events arrive on `onEvent`. */
  subscribe(request: {
    accountId: string;
    subscriptionId: string;
    scope: SettingsSubscriptionScope;
  }): Promise<AccountOrganizationSettingsResponse>;
  unsubscribe(request: { subscriptionId: string }): Promise<void>;
  onEvent(
    listener: (event: AccountOrganizationSettingsEventMessage) => void,
  ): () => void;
  /** Open the owner's web billing page with a modal preopened (strict). */
  paymentHandoff(
    request: SettingsPaymentHandoffRequest & { accountId: string },
  ): Promise<SettingsPaymentHandoffResult>;
  paymentHandoffAvailability(request: {
    accountId: string;
  }): Promise<SettingsPaymentHandoffAvailability>;
  /** Main asks the renderer to open a hosted settings route (agent actions). */
  onOpenRequest(listener: (route: SettingsRoute) => void): () => void;
}

/** One stream event, tagged with the window-local subscription it belongs to. */
export interface AccountOrganizationSettingsEventMessage {
  subscriptionId: string;
  event: SettingsEvent;
}

/** A cloud project a local workspace may link to (CAN-5190). */
export interface CloudProjectLinkCandidate {
  projectId: string;
  name: string;
  matchedRepositories: number;
  totalRepositories: number;
}

/**
 * What the Link to cloud project dialog offers for one workspace: the project
 * it is already linked to, or the Personal projects it matches with the one
 * the server would bind preselected.
 */
export type CloudProjectLinkOptions =
  | { status: 'linked'; projectId: string; name: string }
  | {
      status: 'choose';
      candidates: CloudProjectLinkCandidate[];
      suggestedProjectId: string | null;
    }
  | {
      status: 'unavailable';
      reason:
        | 'signed-out'
        | 'not-supported'
        | 'sharing-off'
        | 'not-personal'
        | 'workspace-unreadable'
        | 'offline';
    };

export interface CloudProjectLinkRequest {
  workspaceId: string;
  target: { kind: 'existing'; projectId: string } | { kind: 'new' };
}

export type CloudProjectLinkErrorCode =
  | 'unavailable'
  | 'not-personal'
  | 'workspace-unreadable'
  | 'project-unavailable'
  | 'too-many-setups'
  | 'busy'
  | 'offline'
  | 'link-failed';

export type CloudProjectLinkResult =
  | { ok: true; projectId: string }
  | { ok: false; code: CloudProjectLinkErrorCode };

/** One of the account's cloud projects, as this device sees it (CAN-5192). */
export interface CloudProjectSetupCatalogEntry {
  projectId: string;
  name: string;
  topology: 'single_repo' | 'multi_repo';
  repositoryCount: number;
  /**
   * `here`: a workspace on this device is bound to it. `needs-attention`: a
   * setup here stopped (`errorCode`) and waits for the user to set it up again.
   */
  state: 'available' | 'setting-up' | 'here' | 'needs-attention';
  /** Why the setup stopped; set only with `needs-attention`. */
  errorCode?: CloudProjectSetupErrorCode;
  workspaceId: string | null;
  /** Repositories added on another device that this one has not decided on. */
  offeredRepositoryCount: number;
}

export type CloudProjectSetupCatalog =
  | { status: 'ok'; projects: CloudProjectSetupCatalogEntry[] }
  | {
      status: 'unavailable';
      reason: 'signed-out' | 'not-supported' | 'sharing-off' | 'offline';
    };

export interface CloudProjectSetupRepositoryOption {
  repositoryId: string;
  name: string;
  /** `host/owner/name`, for the row's description. */
  remoteKey: string;
  /** The project root: always set up with the project. */
  root: boolean;
}

export type CloudProjectSetupOptions =
  | {
      status: 'ok';
      projectId: string;
      name: string;
      topology: 'single_repo' | 'multi_repo';
      repositories: CloudProjectSetupRepositoryOption[];
      /** The remembered clone folder, or null when none was chosen yet. */
      destinationRoot: string | null;
    }
  | {
      status: 'unavailable';
      reason: 'unavailable' | 'offline' | 'project-unavailable';
    };

export interface CloudProjectSetupRequest {
  projectId: string;
  /** The manifest repositories to clone; the root, when there is one, included. */
  repositoryIds: string[];
  /** An absolute folder the project folder is created in. */
  destinationRoot: string;
}

export type CloudProjectSetupErrorCode =
  | 'unavailable'
  | 'already-here'
  | 'busy'
  | 'setup-limit'
  | 'invalid-selection'
  | 'destination-exists'
  | 'needs-credentials'
  | 'clone-failed'
  | 'checkout-blocked'
  | 'checkout-changed'
  | 'workspace-id-in-use'
  | 'project-unavailable'
  | 'offline'
  | 'completion-pending'
  | 'setup-failed';

export type CloudProjectSetupResult =
  | { ok: true; workspaceId: string }
  | { ok: false; code: CloudProjectSetupErrorCode };

/** Pushed on `cloud-projects:setup-progress` while a setup runs. */
export interface CloudProjectSetupProgress {
  projectId: string;
  phase: string;
  state: 'running' | 'done' | 'failed';
  repository?: { index: number; count: number; name: string };
  percent?: number;
  workspaceId?: string;
  errorCode?: CloudProjectSetupErrorCode;
}

/** Why a cloud chats reconnect did not restore the cloud session. */
export type CloudChatsReconnectResult =
  | { ok: true }
  | {
      ok: false;
      reason: 'disabled' | 'unauthenticated' | 'offline' | 'failed';
    };

/** A file the user picked or dropped, read by the renderer for upload. */
export interface CloudChatAttachmentUploadFile {
  name: string;
  mimeType: string;
  bytes: Uint8Array;
}

/** The cloud chat an attachment uploads to: its key and its web core scope. */
export interface CloudChatUploadTarget {
  /** The chat's `web-core:` key. */
  key: string;
  workspaceId: string;
  worktreeId: string;
}

/** A cloud chat attachment upload through main (CAN-5972, CAN-5988). */
export type CloudChatAttachmentUploadResult =
  | {
      ok: true;
      attachmentId: string;
      /** The uploaded attachment as a message send references it. */
      attachment: PortalChatCloudAttachmentRef;
    }
  | {
      ok: false;
      reason:
        | 'disabled'
        | 'unauthenticated'
        | 'too_large'
        | 'rejected'
        | 'offline';
      /** The web core's own words for a refusal it explained (CAN-6369). */
      message?: string;
    };

/** Cloud cowork chats over the web core (CAN-4185). */
export interface CloudChatsApi {
  /** The user's Reconnect: one remint of the cloud session in main, throttled there. */
  reconnect(): Promise<CloudChatsReconnectResult>;
  /** Uploads one file to a cloud chat over main's web core connection. */
  uploadAttachment(
    target: CloudChatUploadTarget,
    file: CloudChatAttachmentUploadFile,
  ): Promise<CloudChatAttachmentUploadResult>;
}

/** Linking a local workspace to its cloud project identity (CAN-5190). */
export interface CloudProjectsApi {
  findLink(workspaceId: string): Promise<CloudProjectLinkOptions>;
  link(request: CloudProjectLinkRequest): Promise<CloudProjectLinkResult>;
  /** The account's cloud projects and which this device has (CAN-5192). */
  setupCatalog(): Promise<CloudProjectSetupCatalog>;
  setupOptions(projectId: string): Promise<CloudProjectSetupOptions>;
  startSetup(
    request: CloudProjectSetupRequest,
  ): Promise<CloudProjectSetupResult>;
  onSetupProgress(
    listener: (progress: CloudProjectSetupProgress) => void,
  ): () => void;
}

export interface OrgProjectsApi {
  sharedMultiRepo: {
    prepare(
      params: PrepareSharedMultiRepoParams,
    ): Promise<PreparedSharedMultiRepo>;
    create(
      params: SharedMultiRepoCreateCommand,
    ): Promise<SharedMultiRepoCreationStatus>;
    getCreation(key: string): Promise<SharedMultiRepoCreationStatus | null>;
    listCreations(): Promise<readonly SharedMultiRepoCreationStatus[]>;
  };
  /**
   * Whether the member can create Code projects in this organization
   * (CAN-3534): Cowork create eligibility plus the server's
   * `org-member-code-projects-v1` capability.
   */
  getMemberCodeEligibility(
    organizationId: string,
  ): Promise<'eligible' | 'ineligible'>;
  /** Decide what Create new makes from a folder, before anything is created. */
  inspectFolder(
    request: InspectOrgMemberFolderRequest,
  ): Promise<OrgMemberFolderInspection>;
  /**
   * The member's organization that holds this folder's or clone URL's
   * repository, so Add project can offer to add it there instead.
   */
  findRepositoryOwner(
    request: OrgRepositoryOwnerRequest,
  ): Promise<OrgRepositoryOwnerLookup>;
  /** Create (or resume, or link) a member's organization Code project. */
  createMemberCodeProject(
    request: CreateOrgMemberCodeProjectRequest,
  ): Promise<CreateOrgMemberCodeProjectResult>;
  /** Create (or resume) a member's multi-repo organization project (CAN-3546). */
  createMemberMultiRepoProject(
    request: CreateOrgMemberMultiRepoProjectRequest,
  ): Promise<CreateOrgMemberMultiRepoProjectResult>;
  /** Which repositories an organization's multi-repo project can take (CAN-3546). */
  checkRepositories(
    request: OrgMultiRepoRepositoryCheckRequest,
  ): Promise<OrgMultiRepoRepositoryCheckResult>;
  setupFromFolder(
    request: OrgProjectSetupFromFolderRequest,
  ): Promise<OrgProjectSetupProgress>;
  linksList(): Promise<OrgProjectLinksListResult>;
  linksDecide(
    request: OrgProjectLinksDecideRequest,
  ): Promise<OrgProjectDeepLinkOpenEvent | null>;
  setupStart(request: {
    projectId: string;
    destinationRoot?: string;
  }): Promise<OrgProjectSetupProgress>;
  setupCancel(request: { projectId: string }): Promise<void>;
  /**
   * Move a Personal project to one of the member's organizations, chosen in
   * the sidebar's Move to organization dialog.
   */
  moveWorkspace(request: OrgProjectMoveRequest): Promise<OrgProjectMoveResult>;
  /** Service-level (CAN-3415); the sidebar's Move uses {@link moveWorkspace}. */
  convertWorkspace(
    request: OrgProjectConvertWorkspaceRequest,
  ): Promise<OrgProjectConversionResult>;
  /** The rollback for {@link convertWorkspace}; works with the flag off. */
  moveBackToPersonal(
    request: OrgProjectMoveBackToPersonalRequest,
  ): Promise<OrgProjectMoveBackResult>;
  onOwnershipChanged(
    callback: (event: OrgProjectOwnershipChangedEvent) => void,
  ): () => void;
  onSetupProgress(
    callback: (progress: OrgProjectSetupProgress) => void,
  ): () => void;
  list(
    request: OrgProjectsListRequest,
  ): Promise<DesktopOrgProjectCatalogSnapshot>;
  refresh(
    request: OrgProjectsRefreshRequest,
  ): Promise<DesktopOrgProjectCatalogSnapshot>;
  setPreference(
    request: OrgProjectsSetPreferenceRequest,
  ): Promise<DesktopOrgProjectCatalogSnapshot>;
  onChanged(
    callback: (snapshot: DesktopOrgProjectCatalogSnapshot) => void,
  ): () => void;
}
