export { STANDALONE_CHAT_PROJECT_ID } from '@canopy/protocol/chat-targets';
export const DEFAULT_CHAT_PROJECT_ID = 'default';
export const DEFAULT_CHAT_PROJECT_NAME = 'Default';

/** LEGACY cowork worktreeId slot; see `@canopy/protocol/chat-targets`. */
export { COWORK_HOME_WORKTREE_ID } from '@canopy/protocol/chat-targets';

/**
 * Cowork workspace id that is always guaranteed to exist — the successor to
 * {@link DEFAULT_CHAT_PROJECT_ID}. The cowork-workspace CRUD layer
 * (`cowork-workspace-crud.ts`) creates this workspace on first list if it is
 * missing, and rejects deleting it, mirroring the old "Default project"
 * guarantee without granting it any other special treatment (it can be
 * renamed like any other cowork workspace). The one-time
 * `standalone-chat` → cowork migration also lands the legacy `'default'`
 * chat project at this same id (see `cowork-migration.ts`).
 */
export {
  DEFAULT_COWORK_WORKSPACE_ID,
  ORG_DEFAULT_COWORK_WORKSPACE_ID_PREFIX,
  defaultCoworkWorkspaceIdForContext,
  isDefaultCoworkWorkspaceId,
  isOrgDefaultCoworkWorkspaceId,
  orgDefaultCoworkWorkspaceId,
} from '@canopy/protocol';

/**
 * Names earlier versions auto-assigned to {@link DEFAULT_COWORK_WORKSPACE_ID}.
 * A stored name outside this set was chosen by the user and is never
 * rewritten by the rename migration, nor withheld by the surfaces that
 * decline to name the catch-all.
 *
 * Re-exported from `@canopy/protocol/ui-labels`, where the shared sidebar and
 * the desktop renderer read the same list without main-process imports.
 */
export { LEGACY_DEFAULT_COWORK_WORKSPACE_NAMES } from '@canopy/protocol';

/**
 * Sentinel project id used by the Plan Exploration chat scope. A plan-explore
 * chat reuses the existing worktree-chat machinery: it flows through the same
 * chatStore / IPC / session paths as a normal worktree chat, but with
 * `projectId = PLAN_EXPLORE_CHAT_PROJECT_ID` and `worktreeId = planId`. The
 * main process resolves the sentinel's real working directory and chat-tabs
 * file via a persisted planId → target registry. Lives alongside
 * {@link STANDALONE_CHAT_PROJECT_ID} so storage keyed by
 * `(projectId, worktreeId)` keeps plan-explore sessions isolated.
 */
export const PLAN_EXPLORE_CHAT_PROJECT_ID = 'plan-explore-chat';

/**
 * Sentinel project id used by the Code Review chat scope. A code-review chat
 * reuses the existing worktree-chat machinery with
 * `projectId = CODE_REVIEW_CHAT_PROJECT_ID` and `worktreeId = <real
 * worktreeId>`. The main process resolves the sentinel's real working
 * directory and chat-tabs file via a persisted worktreeId → project registry,
 * mirroring {@link PLAN_EXPLORE_CHAT_PROJECT_ID}.
 */
export const CODE_REVIEW_CHAT_PROJECT_ID = 'code-review-chat';

/**
 * Sentinel project id for the local Cursor approval-check diagnostic. Main
 * requests approvals under it and the Experiments panel filters on it, so the
 * two sides must share this constant.
 */
export const CURSOR_APPROVAL_CHECK_PROJECT_ID = 'cursor-approval-check';

/**
 * Reserved app-managed workspace id used to key view state (panel layout and
 * other worktree-scoped renderer state) for the shared-container recipient
 * surface, with the containerId in the `worktreeId` slot — the same shape App
 * Advisor uses. It is NOT a user workspace and must never appear in
 * `workspaces/index.json`; `paths.ts` routes it to
 * `app-workspaces/shared-container-viewer/` so nothing is written under the
 * user workspace root. Sealed replica content stays at
 * `shared-containers/{containerId}/revisions/{revisionId}/`, so purging a
 * revision never rewrites view state.
 */
export const SHARED_CONTAINER_VIEWER_PROJECT_ID = 'shared-container-viewer';

/**
 * Composite scope key for the code-review chat sentinel scope. Worktree ids
 * are only unique per workspace, so the sentinel scope's `worktreeId` is the
 * `projectId--worktreeId` composite rather than a bare worktreeId. See
 * {@link buildCodeReviewScopeKey}.
 */
export { buildCodeReviewScopeKey } from './lib/code-review-scope';

// ---------------------------------------------------------------------------
// App Advisor identity constants
// ---------------------------------------------------------------------------

/**
 * Synthetic project id used by the App Advisor (a local, embedded Canopy
 * assistant). Lives alongside `STANDALONE_CHAT_PROJECT_ID` so that storage
 * keyed by `(projectId, worktreeId)` keeps the App Advisor isolated from
 * real projects. The App Advisor is *not* exposed via the Canopy Portal wire
 * protocol — see `packages/protocol/src/portal/index.ts`.
 */
export { APP_ADVISOR_PROJECT_ID } from '@canopy/protocol/chat-targets';

/**
 * Permanent legacy, read-only worktree slot paired with
 * {@link APP_ADVISOR_PROJECT_ID}. Data created before App Advisor Work Entries
 * remains addressable through this id (most notably legacy archives), but new
 * App Advisor chats and messages must use a Work Entry id as `worktreeId`.
 */
export const APP_ADVISOR_WORKTREE_ID = 'global';

// ---------------------------------------------------------------------------
// Pipeline Editor chat identity constants
// ---------------------------------------------------------------------------

/**
 * Synthetic project id used by the embedded Pipeline-Editor chat drawer (the
 * AI assistant that edits the mounted pipeline YAML live and auto-saves). Lives
 * alongside the other chat-scope sentinels so storage keyed by
 * `(projectId, worktreeId)` keeps pipeline-editor sessions isolated from real
 * projects and from the App Advisor. Co-located chat tabs are keyed on this
 * projectId by `resolveChatTabsFilePath`.
 */
export const PIPELINE_EDITOR_PROJECT_ID = 'pipeline-editor';

/**
 * Synthetic worktree id paired with {@link PIPELINE_EDITOR_PROJECT_ID}.
 *
 * MUST be unique and MUST NOT reuse `'global'`. The backend `ipc/chat.ts`
 * routes App Advisor on a *partial* target match
 * (`projectId === APP_ADVISOR_PROJECT_ID || worktreeId === APP_ADVISOR_WORKTREE_ID`)
 * and then throws when the full target does not match. Because
 * {@link APP_ADVISOR_WORKTREE_ID} is `'global'`, a pipeline-editor chat with
 * `worktreeId: 'global'` would satisfy that partial check, enter the App
 * Advisor branch, fail its full-target assertion, and be rejected with
 * "Invalid App Advisor chat target." A distinct `'pipeline-editor'` value
 * avoids the collision entirely. Tab co-location is unaffected —
 * `resolveChatTabsFilePath` keys the directory on the projectId, not the
 * worktree id, so any non-`'global'` value distinct from the other worktree
 * sentinels works.
 */
export const PIPELINE_EDITOR_WORKTREE_ID = 'pipeline-editor';

