// ---------------------------------------------------------------------------
// Canopy Cloud account types
// ---------------------------------------------------------------------------

export type CanopyServerAccountInfo = ProtocolCanopyServerAccountInfo;

export type CanopyServerStatus = ProtocolCanopyServerStatus & {
  secureStorageFailure?: SecureStorageFailure;
};

/**
 * How the saved Canopy Cloud credential authenticates against the cloud.
 *
 * - `oauth`: credential obtained via the desktop OAuth authorization-code flow.
 * - `api_key`: credential entered manually as an API key.
 * - `guest`: credential minted for an anonymous guest session (CAN-934); the
 *   desktop holds a `csk_` key bound to a device-scoped anonymous user.
 */
export type CanopyCloudAuthMode = 'oauth' | 'api_key' | 'guest';

/**
 * Provenance of the saved Canopy Cloud credential. Mirrors the web
 * `UserApiKeySource` contract but uses the desktop-local lowercase spelling.
 *
 * - `manual`: a manually-entered API key.
 * - `oauth_desktop`: a desktop key minted by the OAuth authorization-code flow.
 * - `guest`: a device-scoped key minted for an anonymous guest session
 *   (CAN-934). It satisfies `isCanopyCloudConnected` like any other credential,
 *   and is overwritten with `oauth_desktop` once the guest signs in.
 */
export type CanopyCloudCredentialSource = 'manual' | 'oauth_desktop' | 'guest';

/** Why the renderer asks main to re-check the OS credential store. */
export interface SecureStorageRecheckRequest {
  /** `retry`: the person's Try again. `shown`: a notice appeared; throttled. */
  readonly trigger: 'retry' | 'shown';
}

export interface SecureStorageRecheckResult {
  /** Whether the re-check changed the remembered credential store state. */
  readonly changed: boolean;
}

/**
 * Renderer-safe view of the saved Canopy Cloud account.
 *
 * This is the single cross-boundary settings shape returned by
 * `loadCanopyCloudAccount`, `saveCanopyCloudApiKey`,
 * `clearCanopyCloudApiKey`, the OAuth login/disconnect methods. It
 * intentionally omits the raw API key so most renderers receive only metadata
 * derived from it. The Accounts settings UI can explicitly call
 * `loadCanopyCloudApiKey` to populate its editable secret field, matching the
 * Linear token settings behavior.
 *
 * - `hasApiKey` mirrors whether a credential is currently in secure storage.
 *   It stays `true` for OAuth-created credentials too, for backward
 *   compatibility with callers that only check for a usable credential.
 * - `authMode` / `credentialSource` describe how the saved credential was
 *   obtained. They are `null` when no credential is saved.
 * - `serverApiKeyId` is the cloud-side API-key id for an OAuth-created
 *   credential, used for best-effort self-revocation on disconnect. Omitted
 *   for manual keys.
 * - `capabilities` reflects the most recent well-known endpoint snapshot
 *   for the saved key (empty before the first successful validate/save, or
 *   when no key is saved).
 * - `account` mirrors the most recent account endpoint response.
 * - `organizations` / `teams` mirror the account response so main-process
 *   feature-flag targeting can use the saved snapshot when network probes fail.
 * - `createdAt` / `updatedAt` track the secure-store entry's lifetime.
 * - `storageAvailable` is `false` when the secure-storage policy refuses
 *   new credential writes, so the Accounts UI can show
 *   the matching error path even before any save is attempted.
 *
 * This shape MUST NEVER contain the raw API key.
 */
/**
 * Outcome of a secure-store account read.
 *
 * - `ok` — authoritative, including a genuinely absent account file.
 * - `unavailable` — native storage could not read the ciphertext; typed
 *   metadata distinguishes refusal, probe, and operation failures.
 * - `error` — a filesystem or decoded-data validation failure.
 */
export type CanopyCloudAccountReadStatus = 'ok' | 'unavailable' | 'error';

export interface CanopyCloudAccountPublicState {
  /** Definitive rejection of the current non-guest credential; absent otherwise. */
  sessionExpired?: true;
  secureStorageStatus?: SecureStorageDiagnostic;
  secureStorageFailure?: SecureStorageFailure;
  /**
   * Outcome of the underlying secure-store read, so a renderer can tell an
   * authoritative signed-out state apart from a degraded one.
   *
   * The store collapses every non-`ok` read to a `null` entry, which serializes
   * into a shape indistinguishable from a real sign-out (`hasApiKey: false`, no
   * `account`). Because the read is cached for only `CACHE_TTL_MS`, any ambient
   * re-probe past that window goes back to disk and re-decrypts — so a transient
   * failure would otherwise flip a signed-in user's UI to "Not signed in".
   * Consumers holding last-known-good state must treat anything other than `ok`
   * as inconclusive rather than as proof of a sign-out.
   *
   * A genuinely absent account file is `ok` (the store maps `ENOENT` to
   * `{ status: 'ok', entry: null }`), so `ok` still means authoritative.
   *
   * Optional for backward compatibility: absent ⇒ treat as `ok`.
   */
  read?: CanopyCloudAccountReadStatus;
  hasApiKey: boolean;
  authMode: CanopyCloudAuthMode | null;
  credentialSource: CanopyCloudCredentialSource | null;
  serverApiKeyId?: string;
  capabilities: string[];
  /**
   * First organization eligible for organization-memory search.
   *
   * @deprecated Read `memorySearchOrganizationExternalIds`; org memory searches
   * only the org that owns the work (CAN-3457).
   */
  memorySearchOrganizationExternalId?: string;
  /**
   * Every organization eligible for organization-memory search (lowercase
   * UUIDs). Org memory searches the org that owns the chat's work only when it
   * appears here and never falls back to another entry.
   */
  memorySearchOrganizationExternalIds?: string[];
  account?: CanopyServerAccountInfo;
  /** Current personal org external ID, separate from visible teams. */
  personalOrganizationId?: string;
  personalModelGateway?: CanopyAccountResponse['personalModelGateway'];
  personalModelGatewayEnforcementUnavailable?: boolean;
  organizations?: CanopyOrganizationSummary[];
  teams?: CanopyTeamSummary[];
  /**
   * Org-enforced policies mirrored from the account response, used to lock and
   * force telemetry-sync scopes. Absent ⇒ no enforcement.
   */
  enforcedSettings?: CanopyOrgEnforcedSettings[];
  /** Fail closed when enforced gateway intent could not be normalized. */
  /** Missing policy snapshots fail closed for explicit sharing consent. */
  telemetryEnforcementUnavailable?: boolean;
  modelGatewayEnforcementUnavailable?: boolean;
  /**
   * Per-org billing state mirrored from the account response (CAN-2311), keyed
   * by org externalId. Read by the per-org gates (telemetry fan-out, run share,
   * org memory, org credit pool) so each one blocks exactly the lapsed org and
   * leaves a member's healthy orgs untouched. Absent ⇒ nothing lapsed.
   */
  orgBillingStates?: CanopyOrgBillingState[];
  createdAt?: string;
  updatedAt?: string;
  storageAvailable: boolean;
}

export type ResetUnreadableCanopyCloudAccountResult =
  | {
      status: 'reset';
      account: CanopyCloudAccountPublicState;
      /** Basename only; the secure directory path never crosses IPC. */
      backupFileName: string;
    }
  | {
      status: 'not-needed';
      account: CanopyCloudAccountPublicState;
    };

/**
 * Result of {@link CanopyCloudApi.loadCanopyCloudAiCredits} — the UD AI Credits
 * subscription + balance for the connected cloud account (CAN-771). Surfaced in
 * the Cloud account settings panel.
 */
export interface CanopyCloudAiCreditsState {
  /** True when a cloud account is connected and the lookup was attempted. */
  connected: boolean;
  /** Resolved cloud account email, when connected. */
  email: string | null;
  /** Active subscription, or null when none / not connected / no UD account. */
  subscription: AiCreditsSubscription | null;
  /** Credit balance, or null when not connected / no UD account. */
  balance: AiCreditsBalance | null;
  /**
   * Set when the connected user has no matching UD account (the cloud read
   * returned 404). Distinct from a transient `error`.
   */
  noUdAccount: boolean;
  /** Transient error message when the lookup failed, else null. */
  error: string | null;
  /**
   * Environment-aware URL of the signed-in AI Credits purchase page
   * (`{host}/account/ai-credits?purchase=1`, which auto-opens the purchase flow)
   * that the "Set up a subscription" / "Set up AI Credits" CTAs open. Resolved
   * in the main process from the UD OAuth environment so the renderer never
   * hardcodes a host. Optional so renderer-side fallback states remain valid.
   */
  purchaseUrl?: string;
  /**
   * Environment-aware URL of the signed-in AI Credits management page
   * (`{host}/account/ai-credits`) that the settings "Manage" CTA opens. Resolved
   * in the main process alongside {@link purchaseUrl}. Optional for the same
   * renderer-fallback reason.
   */
  manageUrl?: string;
}

/** Owner context for an AI Credits availability/balance read. */
export type AiCreditsScopeRequest =
  | { kind: 'navigation' }
  | {
      kind: 'work';
      projectId: string;
      worktreeId?: string;
      chatId?: string;
    };

/**
 * Consolidated native-billing availability signal for the usage-exhausted CTA
 * and the model picker (CAN-1235). Computed in the main process from the
 * source-agnostic personal balance (native Canopy ledger OR already-linked UD
 * mirror) plus per-org spendable headroom, so the renderer can classify coverage
 * from a single payload without surfacing any UD-linking path.
 */
export interface NativeAiCreditsAvailability {
  /**
   * Personal AI-credit balance is spendable right now. Source-agnostic: true for
   * a native Canopy wallet OR an already-linked UD account with credits. Derived
   * from `/api/v1/ai-credits/balance` `eligible`, ignoring the `noUdAccount`
   * blocker (we never promote UD linking).
   */
  personalEligible: boolean;
  /** The signed-in user belongs to at least one organization. */
  inOrg: boolean;
  /** The work owner's org carries the `org_credit_pool` capability. */
  orgCreditPoolCovered: boolean;
  /** The work owner's org has spendable headroom right now. */
  orgSpendable: boolean;
  /** The sole organization whose pool was probed for this work. */
  ownerOrganization?: { id: string; name: string };
  /**
   * That organization's current credit pool balance, when its probe resolved.
   * Absent when no organization was probed, the read failed, or the server
   * omitted the balance because the viewer is not an OWNER/ADMIN. Optional for
   * compatibility with older main processes (CAN-3926 sidebar balance).
   */
  ownerOrganizationBalanceCredits?: number;
  /** Native pricing page URL (`{cloudBaseUrl}/pricing`) for the uncovered CTA. */
  pricingUrl: string;
  /**
   * The read could not be completed, so every flag above is a DEFAULT rather
   * than an observation.
   *
   * This loader never throws: a disconnected account or a transient cloud error
   * both degrade to an all-false payload, which is byte-identical to a genuine
   * "nothing can pay". Consumers that make an assertion from that (for example
   * "your org's lapse is why this turn is unpayable") need to tell the two
   * apart, or they will assert it at a user with a funded personal balance who
   * merely lost connectivity. Consumers that only offer a CTA can keep ignoring
   * it and treat the defaults as before.
   */
  inconclusive?: boolean;
}

/**
 * Work-digest cadences for the connected cloud account. Mirrors the web
 * `DigestPreferences` projection returned by
 * `GET/PATCH /api/v1/{brandNamespace}/account/digest-preferences`.
 *
 * These are **cloud-account settings, not local preferences**: they are read
 * from and written to the server on demand and are deliberately NOT mirrored
 * into `preferences.json`, so two machines signed into the same account can
 * never disagree about what the server will send.
 */
/**
 * Alias of the shared wire contract in `@canopy/protocol/digests`, which is the
 * single definition used by the web service layer, the web route validators,
 * and this desktop client. It was previously an independent copy, so adding a
 * cadence meant four coordinated edits with no compiler link between them.
 */
export type CloudDigestPreferences = DigestPreferences;

/**
 * Result of {@link CanopyApi.loadCloudDigestPreferences} /
 * {@link CanopyApi.saveCloudDigestPreferences}. Never throws across IPC.
 *
 * `available` is false when the surface does not exist for this account — no
 * cloud account connected, or the server answered 404 because
 * `canopy-digests-enabled` is off. The renderer hides the section entirely in
 * that case, which keeps the feature flag's single source of truth on the
 * server. `resolved` is false on a transient failure (offline / 5xx) so the
 * caller can show an error instead of misreporting every cadence as off.
 */
export interface CloudDigestPreferencesState {
  available: boolean;
  resolved: boolean;
  preferences: CloudDigestPreferences;
}

/**
 * Result of the tunneled `settings:load-daily-credit-drip` channel — the
 * connected cloud account's daily free-credit drip opt-in, read from
 * `GET /api/v1/ai-credits/daily-drip`. Never throws across IPC. Kept only so
 * older remote controllers can still call this host until CAN-4773 removes the
 * channel.
 *
 * `available` is false when no cloud credential is connected or the server
 * does not offer the route (404, 401/403). `resolved` is false on a transient
 * failure (offline, 5xx, malformed body). `preference` is a placeholder (opted
 * out, undecided, default cap) unless both flags are true.
 */
export interface CloudDailyCreditDripState {
  available: boolean;
  resolved: boolean;
  preference: DailyCreditDripPreference;
}

/**
 * Payload of the tunneled `settings:save-daily-credit-drip` channel, kept for
 * older remote controllers until CAN-4773.
 */
export interface SaveDailyCreditDripRequest {
  enabled: boolean;
}

/**
 * Personal model-library access as the desktop currently knows it.
 *
 * Personal context only. Organization-owned work has its own owner-scoped
 * access returned in `workModelLibrary`; consumers must never borrow this
 * personal value for organization work.
 *
 * - `reported`: this read's own authoritative server answer.
 * - `retained`: this read failed or was unreadable, and `access` is the last
 *   valid answer for the SAME account. Good enough to keep rendering, never
 *   proof of a change — only `reported` may confirm an unlock.
 * - `not-reported`: a successful response from a server that predates the
 *   field. Fall back to the guest rules (guest is limited to the allowlist, a
 *   signed-in account is unlocked).
 * - `unknown`: nothing usable for this account. Render no purchase lock; the
 *   server still enforces.
 */
export type CanopyCloudModelLibraryAccessState =
  | { readonly status: 'reported'; readonly access: ModelLibraryAccess }
  | { readonly status: 'retained'; readonly access: ModelLibraryAccess }
  | { readonly status: 'not-reported' }
  | { readonly status: 'unknown' };

/**
 * Result of {@link CanopyCloudApi.loadCanopyCloudEntitlements} — whether the
 * connected cloud account holds the `data_sync_control` capability, read from
 * `GET /api/v1/entitlements` (CAN-1037 / T21). `canDisableSharing` is a plain
 * projection of the server capability and no longer gates anything on the
 * desktop: every plan may turn sharing Off. `resolved` is false on any
 * transient failure so callers keep last-known-good; a definitive "no
 * capability" (incl. a 404 for an unlinked account) resolves with
 * `canDisableSharing: false`.
 */
export interface CanopyCloudEntitlementsState {
  /** False on a transient failure (offline/auth/5xx) — keep last-known-good. */
  resolved: boolean;
  /**
   * True only when the `data_sync_control` capability is confirmed present.
   * Projection only; it no longer gates sharing on the desktop.
   */
  canDisableSharing: boolean;
  /**
   * True only when the `remote_control` capability is confirmed present.
   * Billing-on-only: under billing-off the `/api/v1/entitlements` mirror never
   * emits `remote_control`, so this is `false` even though Remote Control is
   * available to everyone (the server fails open and mints `portal-v1`). This is
   * NOT the availability gate — the authoritative desktop signal is the account
   * `portal-v1` capability. Provided for completeness/telemetry.
   */
  canRemoteControl: boolean;
  /**
   * Primary grant source by precedence (subscription > trial > org_seat > none).
   * `'none'` when unresolved or the account holds no billing grant. Drives the
   * sidebar effective-plan subtitle.
   */
  source: EntitlementSource;
  /** Primary plan (server-provided display name), or null when there is none. */
  plan: { key: string; displayName: string } | null;
  /** Trial state, or null when there is no trial. `active` is false once ended. */
  trial: { active: boolean; endsAt: string } | null;
  /**
   * Org this user can manage billing for (OWNER/ADMIN), for deep-link routing to
   * `/organization/{id}/settings?tab=billing`. `id` is the org externalId.
   * Present only when exactly one org is manageable; null otherwise.
   */
  billingManageableOrg: { id: string; name: string } | null;
  /**
   * Highest-priced plan the user should SEE in the sidebar subtitle, ranked by face
   * price across their own live subscription and the orgs they manage
   * (OWNER/ADMIN), including a trialing org. So an owner of a pricier (even
   * trialing) org sees that plan rather than their cheaper personal one. Distinct
   * from `plan`/`source` (the wallet-primary grant); null when unresolved or
   * there is nothing higher to show (a plain personal trial stays represented by
   * `trial`/`source: 'trial'`).
   */
  displayPlan: {
    key: string;
    displayName: string;
    source: EntitlementSource;
  } | null;
  /** Display/navigation-only conversion tier and exact billing owner. */
  billingPresentation: BillingPresentation | null;
  /**
   * True only when the server reports free app access: every capability is
   * granted without a subscription, so plan, trial, and upgrade surfaces are
   * hidden and only AI Credits remain purchasable. Optional because older
   * servers omit it; a missing value means tier behavior.
   */
  freeAccess?: boolean;
  /**
   * Personal model-library access. Optional because a main process that
   * predates the field omits it; a missing value means `unknown`.
   */
  modelLibrary?: CanopyCloudModelLibraryAccessState;
  /**
   * Opaque identity of the account {@link modelLibrary} describes, or null
   * when no credential is saved. Renderers compare it across reads so one
   * account's access is never shown, or acted on, for another.
   */
  modelLibraryAccountKey?: string | null;
  /** Access for the authorized scope passed to the read, separate from personal access. */
  workModelLibrary?: CanopyCloudModelLibraryAccessState;
  modelLibraryOwnerKey?: string;
}

/** Result of the live mobile-activation probe used by desktop promotions. */
export interface MobileActivationState {
  /** False on a transient failure; consumers retain their last-known-good. */
  resolved: boolean;
  /** True only when an iOS or Android device token exists for the account. */
  hasMobileActivation: boolean;
}

/** Options for the live desktop mobile-activation probe. */
export interface MobileActivationLoadOptions {
  /** Bypass the short TTL after the app returns to the foreground. */
  forceRefresh?: boolean;
}

export type GitHubTokenType = 'classic' | 'fine-grained' | 'gh-cli' | 'unknown';

/**
 * Which credential source to validate when probing GitHub permissions.
 * - `'pat'` / `'oauth'`: probe ONLY that source — no fallback. Used by the
 *   Accounts settings UI so the Permissions panel reflects the user's
 *   currently-selected auth mode rather than a resolved-token mix.
 * - `'any'`: probe whichever credential `resolveGitHubToken` returns
 *   (PAT first, then gh CLI fallback). Used by callers that just need to
 *   know whether *some* usable GitHub token exists, e.g. enabling the
 *   "List repos" picker in worktree creation.
 */
export type GitHubPermissionSource = 'pat' | 'oauth' | 'any';

export interface GitHubPermissionsRequest {
  source: GitHubPermissionSource;
}

export type PermissionState = 'granted' | 'missing' | 'unknown';

export interface GitHubPermission {
  scope: string;
  label: string;
  description: string;
  required: boolean;
  state: PermissionState;
}

export interface GitHubPermissionsStatus {
  tokenAvailable: boolean;
  tokenType: GitHubTokenType;
  scopes: string[];
  permissions: GitHubPermission[];
  canListRepos: boolean;
  error: string | null;
}

export interface GitHubRepoSummary {
  fullName: string;
  ownerLogin: string;
  name: string;
  description: string | null;
  cloneUrl: string;
  sshUrl: string;
  htmlUrl: string;
  isPrivate: boolean;
  isFork: boolean;
  isArchived: boolean;
  defaultBranch: string;
  updatedAt: string | null;
}

export type CliPathState =
  | 'outdated'
  | 'unsupported'
  | 'missing'
  | 'installed'
  | 'correct-symlink'
  | 'foreign-symlink'
  | 'regular-file';

export type CliPathUnsupportedReason = 'dev' | 'unsupported-platform';

export interface CliPathStatus {
  state: CliPathState;
  reason?: CliPathUnsupportedReason;
  /**
   * macOS: managed symlink under `/usr/local/bin/canopy`.
   * Linux: per-user launcher under `XDG_BIN_HOME` or `~/.local/bin`.
   * Windows: `null`; consumers should rely on `managedPathEntry`.
   */
  symlinkPath: string | null;
  /**
   * macOS and Linux: target of `symlinkPath` when it exists, otherwise `null`.
   * Windows: always `null`.
   */
  symlinkTarget: string | null;
  /**
   * Full path to the bundled Canopy CLI executable. On Windows this includes
   * the `canopy.exe` extension. `null` when the bundled CLI cannot be located
   * (e.g. running from a dev tree before the build step).
   */
  bundledCliPath: string | null;
  /**
   * Windows: the directory the IPC handler manages inside
   * `HKCU\Environment\Path`. Present when the platform performs PATH
   * management for the Canopy CLI. Linux: launcher directory; installation
   * does not edit PATH or shell files. Absent on macOS and unsupported platforms.
   *
   * The renderer must tolerate this field being absent when the main process
   * ships an older build that does not yet emit it.
   */
  managedPathEntry?: string;
}

export interface CliInstallResult {
  success: boolean;
  error: string | null;
}

export interface UpdateInfoData {
  version: string;
  releaseDate?: string;
  releaseNotes?: string | null;
  /** Linux .deb updates are metadata-only. This is the official brand page. */
  manualDownload?: {
    url: string;
    guidance: string;
    checksum: { algorithm: 'SHA-512' | 'SHA-256'; value: string };
  };
  /** Repository-installed Linux packages update only through the system package manager. */
  packageManagerUpdate?: {
    guidance: string;
    command: string;
  };
}

export type UpdateReleaseFlavor = 'stable' | 'rc' | 'internal';

export type TargetUpdateRelation = 'upgrade' | 'current' | 'downgrade';

export interface TargetUpdateInfo {
  tag: string;
  version: string;
  releaseDate?: string;
  relation?: TargetUpdateRelation;
}

export interface TargetUpdateVersionItem extends TargetUpdateInfo {
  name?: string;
}

export interface TargetUpdateVersionListRequest {
  query?: string;
  cursor?: string;
  limit?: number;
}

export interface TargetUpdateVersionListResponse {
  items: TargetUpdateVersionItem[];
  nextCursor: string | null;
}

export interface TargetUpdateRequest {
  tag: string;
}

export interface DownloadProgressData {
  percent: number;
  bytesPerSecond: number;
  transferred: number;
  total: number;
}

export type UpdatePhase =
  | 'idle'
  | 'checking'
  | 'available'
  | 'downloading'
  | 'downloaded'
  | 'not-available'
  | 'error';

export interface UpdateState {
  phase: UpdatePhase;
  info?: UpdateInfoData;
  target?: TargetUpdateInfo;
  progress?: DownloadProgressData;
  message?: string;
  checkedAt?: string;
  installPending?: boolean;
}

export const ACTIONABLE_PHASES = new Set<UpdatePhase>([
  'available',
  'downloading',
  'downloaded',
]);

export type UpdateEvent =
  | { type: 'checking' }
  | { type: 'available'; info: UpdateInfoData }
  | { type: 'not-available' }
  | { type: 'download-progress'; progress: DownloadProgressData }
  | { type: 'downloaded'; info: UpdateInfoData }
  | { type: 'install-pending'; pending: boolean }
  | { type: 'error'; message: string };

/**
 * Cloud telemetry sync status snapshot emitted by the main-process
 * `TelemetrySyncService`. Desktop-only contract; lives next to {@link UpdateState}
 * because the renderer surfaces it through the sidebar account menu's
 * cloud-sync row (`SidebarAccountMenu.tsx`), mirroring the software-update
 * pill stack.
 *
 * Main owns the network truth here. The renderer merges this with Canopy Cloud
 * account connectivity to derive the displayed phase.
 */
export interface TelemetrySyncStatus {
  /** True while a flush has committed to a network upload. */
  isSyncing: boolean;
  /**
   * Count of queued items not yet uploaded: turns, plans, PRs, pipeline runs
   * and summaries. Envelope metadata and attention transitions are not counted.
   */
  pendingCount: number;
  /** True when at least one data type is opted in to sharing. */
  sharingActive: boolean;
  /** ISO timestamp of the last successful upload, or null if never synced. */
  lastSyncedAt: string | null;
  /** ISO timestamp of the last upload error, or null. */
  lastErrorAt: string | null;
  /** Last upload error reason, or null when the last flush succeeded. */
  lastError: 'upload-failed' | null;
  /**
   * Set while sync should be running but is not (CAN-3512), so the renderer
   * can say `Sync paused` instead of failing silently. Composed by the
   * main-process pause monitor (`services/telemetry-sync-pause.ts`) at the IPC
   * boundary; the service's own snapshot omits it. Absent or null means not
   * paused.
   */
  pausedReason?: TelemetrySyncPausedReason | null;
}

/**
 * Why telemetry sync is paused (CAN-3512).
 *
 * - `queue-stalled`: the oldest queued item has waited past the stall threshold
 *   and nothing uploaded in that time.
 */
export type TelemetrySyncPausedReason = 'queue-stalled';

export interface TelemetrySyncApi {
  getStatus(): Promise<TelemetrySyncStatus>;
  onStatusEvent(cb: (status: TelemetrySyncStatus) => void): () => void;
  /**
   * Report coarse human presence in a worktree (CAN-3195).
   *
   * Fire-and-forget and heavily throttled by the renderer: the server only
   * needs to know whether a human was at the machine recently, so it can stop
   * telling them their run finished while they are watching it finish.
   *
   * Desktop liveness is NOT presence — the app is almost always running — so
   * this is the only thing that establishes it.
   */
  recordActivity(projectId: string, worktreeId: string): void;
}

export type BranchNamePrefixMode = 'github' | 'custom' | 'none';

export interface BranchDisplayMappingSettings {
  replaceHyphens: boolean;
  capitalize: boolean;
}

export interface BranchDisplayMapping {
  id: string;
  label: string;
  matcher: string;
  result: string;
  settings: BranchDisplayMappingSettings;
  enabled: boolean;
  builtin: boolean;
  examples: string[];
  readonlyExampleCount: number;
}

// ---------------------------------------------------------------------------
// Feedback bundle types
// ---------------------------------------------------------------------------

/**
 * The exhaustive list of application areas the user can attribute a feedback
 * report to. Both backend and frontend must validate against this list.
 */
export const FEEDBACK_AREAS = [
  'overview',
  'worktrees',
  'chat',
  'pipelines',
  'plugins',
  'audit-trail',
  'usage',
  'settings',
] as const;

export type FeedbackArea = (typeof FEEDBACK_AREAS)[number];

/**
 * One workspace selection inside a feedback report. Used only when
 * `area === 'worktrees'`. `worktreeIds` lists the specific worktrees the user
 * has chosen to attach for the given workspace.
 */
export interface FeedbackWorkspaceSelection {
  workspaceId: string;
  worktreeIds: string[];
}

/**
 * Request shape for `IPC_CHANNELS.feedbackPrepare`.
 *
 * Contract semantics (must be respected by both renderer and main):
 * - `description` must be a non-empty string after trimming.
 * - `area` must be one of the values in `FEEDBACK_AREAS`.
 * - `workspaceSelections` is only meaningful for `area === 'worktrees'`. For
 *   any other area the renderer must send `[]` (or omit), and the backend may
 *   treat any value as ignorable.
 * - `chatProjectIds` is only meaningful for `area === 'chat'`. For any other
 *   area the renderer must send `[]` (or omit), and the backend may treat any
 *   value as ignorable.
 * - `includeChatDetails` is only meaningful for `area === 'worktrees'` or
 *   `area === 'chat'`. For any other area the renderer must send `false` (or
 *   omit).
 * - `includePipelineExecutions` is only meaningful for
 *   `area === 'worktrees'`. When false or omitted, the backend may include a
 *   minimal generated pipeline-state snapshot, but must not include full
 *   pipeline execution directories for selected worktrees.
 * - All `workspaceId`, `worktreeId`, and `chatProjectId` values are
 *   user-supplied strings that the backend must validate before any
 *   filesystem use.
 */
export interface FeedbackPrepareRequest {
  error?: FeedbackReportError;
  description: string;
  area: FeedbackArea;
  workspaceSelections?: FeedbackWorkspaceSelection[];
  chatProjectIds?: string[];
  includeChatDetails?: boolean;
  includePipelineExecutions?: boolean;
}

/**
 * Response shape for `IPC_CHANNELS.feedbackPrepare`. The response always
 * reflects a successfully written zip on disk in the user's Downloads
 * directory. Errors must be thrown so they surface as a rejected `invoke()`
 * to the renderer.
 */
export interface FeedbackPrepareResponse {
  filename: string;
  absolutePath: string;
  createdAt: string;
  sizeBytes: number;
}

/**
 * The two kinds of first-class feedback report a user can submit. Each maps to
 * a distinct label on the created Linear issue. "Feedback" is the branding;
 * bug reporting is one mode of it.
 */
/**
 * Slim, serializable subset of the renderer's current-UI-state snapshot that is
 * attached to a feedback report so the triaging team knows where the user was
 * and what they were doing. All fields are best-effort and optional: the
 * renderer includes whatever it can resolve from
 * `useCurrentUiStateStore.getState().envelope.snapshot`.
 */
export type FeedbackContextSnapshot = FeedbackReportContext;

/**
 * Request shape for `IPC_CHANNELS.feedbackSubmit`.
 *
 * - `type` must be one of {@link FEEDBACK_REPORT_TYPES}.
 * - `description` must be a non-empty string after trimming.
 * - `title` is optional; when blank the backend derives one from the
 *   description.
 * - `context` is the auto-captured UI snapshot; every field is optional.
 * - `includeDiagnostics` controls whether the diagnostics zip is built,
 *   uploaded, and attached to the created Linear issue.
 */
export type FeedbackSubmitRequest = FeedbackReportSubmission;
export type FeedbackDiagnosticsPrepareRequest = {
  context: FeedbackReportContext;
  error?: FeedbackReportError;
};

/**
 * Response shape for `IPC_CHANNELS.feedbackSubmit`. Returned once the report has
 * been filed (diagnostics attachment is best-effort and does not fail the
 * submission). Errors must be thrown so they surface as a rejected `invoke()` to
 * the renderer.
 *
 * Intentionally carries no issue identifier or tracker URL: the report is filed
 * into an internal issue tracker, so surfacing that identifier/link to the user
 * would leak internal details. The renderer only needs to know it succeeded.
 */
export interface FeedbackSubmitResponse extends FeedbackReportResult {
  submitted: true;
}

// ---------------------------------------------------------------------------
// Turn-level thumbs up/down feedback (CAN-1521)
// ---------------------------------------------------------------------------

/**
 * Request shape for `IPC_CHANNELS.turnFeedbackRate`. Step 1 of the flow: one
 * click records the rating. `clientUserMessageId` is the renderer's per-turn
 * message id and is the correlation key; `clientChatId` guards the
 * `nextMsgId()` collision case (the counter resets on renderer reload, so two
 * reloads can mint the same first id in the same millisecond).
 */
export interface TurnFeedbackRateRequestIpc {
  clientUserMessageId: string;
  clientChatId: string;
  projectId?: string;
  worktreeId?: string;
  rating: TurnFeedbackRating;
  provider?: string;
  model?: string;
  eventType?: string;
  chatMode?: string;
}

/**
 * Response for `IPC_CHANNELS.turnFeedbackRate`. Never rejects: when the request
 * cannot reach Canopy Cloud (signed out, offline, revoked key) the rating is
 * queued in the local outbox and `queued` is true, so the UI still shows the
 * thumb as recorded.
 */
export interface TurnFeedbackRateResponse {
  recorded: boolean;
  queued: boolean;
  feedbackId?: string;
}

/**
 * Request shape for `IPC_CHANNELS.turnFeedbackDetail`. Step 2: amends the row
 * created by step 1 with a reason and/or comment. Skipping the dialog simply
 * never sends this, so skip can never undo the rating.
 */
export interface TurnFeedbackDetailRequestIpc {
  clientUserMessageId: string;
  feedbackId?: string;
  reason?: TurnFeedbackReason;
  comment?: string;
}

/** Response for `IPC_CHANNELS.turnFeedbackDetail`. Never rejects. */
export interface TurnFeedbackDetailResponse {
  recorded: boolean;
  queued: boolean;
}

/**
 * Request shape for `IPC_CHANNELS.turnFeedbackClear`. Sent when the user clicks
 * the already-selected thumb to retract a rating. `feedbackId` is absent when
 * the rating never reached the server, in which case only the queued outbox
 * entry is dropped — a retracted rating must never upload on the next flush.
 */
export interface TurnFeedbackClearRequest {
  clientUserMessageId: string;
  feedbackId?: string;
}

/** Response for `IPC_CHANNELS.turnFeedbackClear`. Never rejects. */
export interface TurnFeedbackClearResponse {
  cleared: boolean;
}

/** Request shape for `IPC_CHANNELS.turnFeedbackList`. */
export interface TurnFeedbackListRequest {
  clientChatId: string;
}

/**
 * Response for `IPC_CHANNELS.turnFeedbackList`. Merges server rows with any
 * still-pending outbox entries so a queued thumb keeps rendering across a
 * restart. Resolves with an empty list rather than rejecting on failure.
 */
export interface TurnFeedbackListResponseIpc {
  feedback: TurnFeedbackSummary[];
}

/**
 * One queued rating awaiting upload. A queued rating is complete on its own —
 * there is no bundle to hold or rebuild at flush time — so the outbox only ever
 * replays the rate call and, when present, the detail amendment.
 */
export interface TurnFeedbackOutboxEntry {
  clientUserMessageId: string;
  clientChatId: string;
  rating: TurnFeedbackRating;
  queuedAt: number;
  /** Serialized owner resolved when the rating was made. */
  workOwner?: string;
  provider?: string;
  model?: string;
  eventType?: string;
  chatMode?: string;
  /**
   * Desktop version at the moment the turn was rated — stamped when the entry
   * is queued rather than at flush time, so a rating queued on one build and
   * uploaded after an update still reports the build the turn actually ran on.
   */
  appVersion?: string;
  reason?: TurnFeedbackReason;
  comment?: string;
  /**
   * Canopy Cloud account id that was signed in when this rating was queued, or
   * `undefined` when it was queued while signed out.
   *
   * The flush is triggered by an account change, so without this binding the
   * whole outbox uploads to whichever account signs in next. On a shared
   * machine that would post user A's ratings — and their free-text comments —
   * under user B, who could then read them back via
   * `GET /api/v1/feedback/turns/{feedbackId}`. Flush therefore sends only
   * entries that are unbound (`undefined`, the rate-as-guest case this feature
   * is built around) or bound to the account currently signed in.
   */
  accountId?: string;
}

/** Persisted shape of `{dataDir}/turn-feedback-outbox.json`. */
export interface TurnFeedbackOutboxFile {
  version: 1;
  entries: TurnFeedbackOutboxEntry[];
}

/**
 * One turn's rating as the renderer holds it, keyed by `userMessageId` on
 * `PersistedChatTab.turnFeedback`.
 *
 * `syncState` is persisted deliberately: a rating queued in the local outbox
 * must still render as recorded after a restart, and a `failed` upload keeps
 * the rating rather than silently reverting the user's click.
 */
export interface TurnFeedbackEntry {
  rating: TurnFeedbackRating;
  syncState: 'pending' | 'synced' | 'failed';
  ratedAt: number;
  reason?: TurnFeedbackReason;
  hasComment?: boolean;
  feedbackId?: string;
}

// ---------------------------------------------------------------------------
// Discovery types (slim versions of SDK types for serialization)
// ---------------------------------------------------------------------------

export interface SlashCommandData {
  name: string;
  description: string;
  argumentHint?: string;
  displayName?: string;
  insertText?: string;
  /**
   * Which section of the Fast Slash Menu this row belongs to. `'discovered'`
   * rows are already enabled/available for the tab; `'available'` rows must be
   * enabled (via {@link InvocableInventoryEntry.enableRef}) before insertion.
   */
  section?: 'discovered' | 'available';
  /**
   * Concrete invocable-inventory row backing this slash command, when this row
   * originates from the invocable inventory. `desktop-shared` owns
   * {@link InvocableInventoryEntry}, so the typed field lives here. The
   * boundary-safe `SlashCommandOption` in `@canopy/ui-rich` carries this only
   * through its opaque `data?: unknown` slot.
   */
  inventoryEntry?: InvocableInventoryEntry;
}

export interface McpServerStatusData {
  name: string;
  status: 'connected' | 'failed' | 'needs-auth' | 'pending' | 'disabled';
  serverInfo?: { name: string; version: string };
  error?: string;
  scope?: string;
  tools?: { name: string; description?: string }[];
}

export interface WorktreeDiscovery {
  slashCommands: SlashCommandData[];
  mcpServers: McpServerStatusData[];
  discoveredAt: string;
  providerType?: AgentProviderType;
  /**
   * Plugins this chat turned on whose Mod its next Claude launch leaves out,
   * so the composer can say so before a message is sent. A restored tab keeps
   * it; the notice reads each Mod's current state, so one allowed since then
   * shows as allowed.
   */
  skippedMods?: ClaudeModsSkippedEntry[];
}

// ---------------------------------------------------------------------------
// Worktree / Project types
// ---------------------------------------------------------------------------

/** Persisted ordering choice for a sidebar section. */
export type SidebarSortMode = 'last-updated' | 'manual';

export type WorktreeHealthIssueCode =
  | 'missing-worktree-path'
  | 'missing-git-metadata'
  | 'invalid-git-worktree'
  | 'missing-repository'
  | 'git-error';

export interface WorktreeHealthRepoIssue {
  repoId: string;
  repoName: string;
  repoPath: string;
  code: WorktreeHealthIssueCode;
  message: string;
  gitError?: string;
}

export interface WorktreeHealthIssue {
  status: 'broken';
  code: WorktreeHealthIssueCode;
  message: string;
  checkedAt: string;
  worktreePath: string;
  gitError?: string;
  repoIssues?: WorktreeHealthRepoIssue[];
  /** The source branch has no initial commit; other branches may have commits. */
  failureReason?: 'source-no-commits';
  /** Child source identity for multi-repo setup; absent for the source root. */
  sourceRepoId?: string;
}

/**
 * Persisted record describing a compatibility symlink created on a worktree
 * (typically by the Adhoc Multi-Repo combine flow). The renderer treats these
 * as a transport-layer artifact only — destination worktrees may surface them
 * informationally without re-running identity logic.
 *
 * `path` and `targetPath` are always absolute paths. `repoId` is omitted for
 * root-level (worktree-root) symlinks and set for per-repo symlinks.
 */
export interface WorktreeCompatibilitySymlink {
  path: string;
  targetPath: string;
  reason: 'adhoc-multi-repo-transition';
  sourceWorkspaceId: string;
  sourceWorktreeId: string;
  repoId?: string;
  createdAt: string;
}

/**
 * Persisted marker recorded on a destination worktree created by the adhoc
 * multi-repo combine flow. Present only on worktrees that were created (or
 * extended) as the destination side of a transition; absent on standalone
 * worktrees.
 */
export interface AdhocMultiRepoTransitionSource {
  sourceWorkspaceId: string;
  sourceWorktreeId: string;
  sourceRepoIds: string[];
  repoMappings?: AdhocMultiRepoRepoMapping[];
  selectedRepoIdRewrites?: Record<string, string>;
  sourceRootRepoIdRewrite?: string;
  filePathRewrites?: Array<{ fromRoot: string; toRoot: string }>;
  /**
   * Present when this destination worktree was created by joining an
   * existing worktree (`workspace:combine-worktree-with-existing-worktree`).
   * Lets the retry-on-reopen path return the joined side's migration payload.
   */
  joinedWorktreeMigration?: AdhocJoinedWorktreeMigration;
  createdAt: string;
}

/** Desktop-owned create identity. Never authorizes automatic compensation. */
export interface WorktreeCreationIdentity {
  operationId: string;
  state: 'pending' | 'complete' | 'recovery-required';
  phase: 'reserved' | 'git-setup' | 'source-root-repair' | 'git-ready';
  checkouts: { repositoryPath: string; checkoutPath: string }[];
}

export type WorktreeLabelSource = 'generated' | 'manual';

export interface WorktreeData {
  creation?: WorktreeCreationIdentity;
  /** Authority-owned local replicas; absent input is a legacy never-recorded row. */
  replica?: WorktreeReplicaState;
  id: string;
  branchName: string;
  createdAt: string;
  /** Files-only restore provenance: the checkout has no portable Git pointer. */
  restoredFromFilesOnlyArchiveId?: string;
  /** User pin within the owning workspace's sidebar section. */
  pinned?: boolean;
  /** Durable activity watermark used by workspace Auto Delete. */
  lastTouchedAt?: string;
  /**
   * Durable identity guard for an explicit branch deletion that may need to
   * resume after the worktree checkout has already been removed.
   */
  pendingArchiveBranchDeletion?: {
    referenceRepoPath: string;
    repositoryIdentity: string;
    branchName: string;
    expectedTip: string;
  };
  /** Durable compare-before-delete guards for multi-repository archive retries. */
  pendingArchiveBranchDeletions?: Array<{
    repoId: string;
    referenceRepoPath: string;
    repositoryIdentity: string;
    branchName: string;
    expectedTip: string;
  }>;
  discovery?: WorktreeDiscovery;
  branchPromptSent?: boolean;
  status?: 'active' | 'done';
  /**
   * Optional user-set display label for this worktree. When present it
   * overrides the computed branch display name as the sidebar row's primary
   * name. Cleared (key omitted) when the user empties the label, so the branch
   * display name is restored as the fallback. Does not rename the git branch.
   */
  label?: string;
  /**
   * Who chose `label`. `generated`: the worktree summary helper named it from
   * the conversation and may rename it while `labelProvisional` is set. A
   * label with no source was set by a person or an explicit agent action (or
   * saved before provenance existed) and is never renamed automatically.
   * `manual` with no label records that a person cleared the label, so the
   * branch name stays the display name.
   */
  labelSource?: WorktreeLabelSource;
  /** Set only with a generated label the conversation has not yet settled. */
  labelProvisional?: true;
  /** Execution ids whose current paused/terminal pipeline state has been acknowledged in the UI. */
  seenPipelineExecutionIds?: string[];
  /** The user-configured base branch for this worktree (e.g. "main"). */
  trackedBaseBranch?: string | null;
  /** Per-repo base-branch overrides keyed by repo id. */
  trackedRepoBaseBranches?: Record<string, string>;
  /** Persisted PR status snapshot used to bootstrap the UI and poll queues. */
  lastKnownPrStatus?: WorktreePrStatus | null;
  /** Hook keys (matching HookDescriptor.hookKey) the user has paused in this worktree. */
  pausedHookKeys?: string[];
  /**
   * Per-worktree override for the sidebar branch-grouping behavior, taking
   * precedence over the global `groupChildBranchesWithBase` preference.
   * - `'group'`: force this worktree to nest under its base-branch parent
   *   (when an eligible parent exists), even if grouping is globally disabled.
   * - `'ungroup'`: force this worktree to stay at the top level, even if
   *   grouping is globally enabled.
   * Absent = follow the global preference.
   */
  branchGroupingOverride?: 'group' | 'ungroup';
  /**
   * Visual parent retained after an automatic merge retarget changes this
   * worktree's operational Git base branch. Ignored when the referenced
   * worktree is absent; grouping overrides still take precedence.
   */
  branchGroupingParentWorktreeId?: string;
  /**
   * Chat badge summary derived from this worktree's persisted chat tabs at
   * write time. See {@link WorktreeChatBadgesSummary}. Absent for worktrees
   * whose chats have never been (re)saved since the field was introduced —
   * consumers treat absence as "no badges".
   */
  chatBadges?: WorktreeChatBadgesSummary;
  /** Persisted marker for worktrees that cannot currently be read as valid Git worktrees. */
  healthIssue?: WorktreeHealthIssue;
  /**
   * When true, the worktree is hidden from the sidebar by default.
   * Persisted only when explicitly hidden; absent/false rows omit the key
   * to mirror the optional-omit convention used by other flags above.
   */
  hidden?: boolean;
  /**
   * Two-phase worktree creation marker.
   * - `'git-pending'`: Phase A persisted the row and reserved the parent directory; Phase B (git operations) is still running.
   * - `'git-ready'`: Phase B completed successfully.
   * Absent = ready (back-compat for existing rows persisted in `worktrees.json`; no migration needed).
   */
  setupPhase?: 'git-pending' | 'git-ready';
  /**
   * Explicit child-repository scope for this multi-repo worktree. Missing
   * means every configured repository; an empty array is workspace-root-only.
   */
  includedRepoIds?: string[];
  /** Split destination data must be retained until completion or explicit repair. */
  splitRecoveryRequired?: true;
  /**
   * Compatibility symlinks persisted on this worktree by the adhoc multi-repo
   * combine flow. Canonical record — the renderer never recomputes these.
   * Missing means "no symlinks" (treated as an empty array by consumers).
   */
  compatibilitySymlinks?: WorktreeCompatibilitySymlink[];
  /**
   * Present only on destination worktrees created by an adhoc multi-repo
   * transition. Tracks which source worktree/repos contributed to this
   * destination so the renderer (and backend cleanup) can reason about the
   * relationship without re-running identity matching.
   */
  adhocTransitionSource?: AdhocMultiRepoTransitionSource;
}

export interface WorktreeHealthCheckRequest {
  projectId: string;
  worktreeId: string;
}

export interface WorktreeHealthCheckResponse {
  healthy: boolean;
  worktree: WorktreeData;
  issue?: WorktreeHealthIssue;
}

export type { WorkspaceType };

export type ActivitySectionId =
  | 'plugins'
  | 'summary'
  | 'changed-files'
  | 'pull-request'
  | 'background-processes'
  | 'plans'
  | 'pipeline-runs'
  /** The entry's observed cost. */
  | 'cost'
  | 'scripts'
  | 'hooks'
  | 'terminals'
  | 'todo'
  | 'mcp-servers'
  | 'notes'
  | 'prompts'
  | 'attachments'
  | 'memory';

/**
 * Which UX surface an activity section is available on. `'worktree'` is the
 * Code-workspace worktree activity rail; `'cowork'` is the Cowork workspace
 * activity rail (no git, so git-bound sections are worktree-only).
 */
export type ActivitySurface = 'worktree' | 'cowork';

export interface WorktreeRepoSummary {
  name: string;
  description: string;
}

export interface WorktreeSummaryData {
  title: string;
  description: string;
  highlights: string[];
  repos?: WorktreeRepoSummary[];
  generatedAt: string;
  turnCountAtGeneration: number;
  lastFullRefreshAt: string;
  lastFullRefreshTurnCount: number;
}

/**
 * One persisted summary snapshot. `snapshotId` is a stable client-authoritative
 * string id assigned at write time — a UUID for snapshots created on the v2 path,
 * or a deterministic `legacy-<hash>` id for snapshots upgraded from a legacy v1
 * file. It flows local file → telemetry wire → server table, making server
 * append idempotent.
 */
export interface WorktreeSummarySnapshot {
  snapshotId: string;
  summary: WorktreeSummaryData;
  /** Recorded on snapshots generated since Summary publication (LD06). */
  provenance?: WorktreeSummaryProvenance;
}

/**
 * The helper invocation that generated a snapshot, captured before the
 * provider was called, so a model switch during generation cannot
 * misattribute it. Readers and telemetry ignore it.
 */
export interface WorktreeSummaryProvenance {
  /** One helper invocation: the Ledger actor that publishes the snapshot. */
  generationId: string;
  harness: string | null;
  model: string | null;
  thinkingEffort: string | null;
  /** The generation's Audit Trail task. */
  observedTaskKey: string | null;
  capturedAt: string;
  /**
   * True only when the Ledger was on at generation time. Such a snapshot is
   * published to the Ledger once: right after it is written, or by startup
   * reconciliation.
   */
  ledgerPublishable?: boolean;
}

export interface WorktreeSummaryFile {
  version: 2;
  /** Latest snapshot pointer; kept so all current readers stay unchanged. */
  summary: WorktreeSummaryData;
  /** Append-on-change history, oldest first, deduped by content hash. */
  history: WorktreeSummarySnapshot[];
}

/** Per-worktree resolved hooks/scripts, keyed by worktreeId on the parent item. */
export interface WorktreeEffectiveOverrides {
  effectiveHooks?: HookOverrides;
  effectiveScripts?: ScriptOverrides;
  /** Multi-repo only: per-repo resolved hooks/scripts keyed by repoId. */
  repos?: Record<
    string,
    {
      effectiveHooks?: HookOverrides;
      effectiveScripts?: ScriptOverrides;
    }
  >;
}

export interface ProjectData {
  privateMemory?: boolean;
  privateMemoryManagedBy?: 'organization';
  id: string;
  name: string;
  repoPath: string;
  color: string;
  worktrees: WorktreeData[];
  collapsed: boolean;
  order: number;
  /** User pin within the top-level Projects section. */
  pinned?: boolean;
  /** Ordering mode for this workspace's worktree rows. */
  itemSortMode?: SidebarSortMode;
  defaultPluginSelections?: ChatTabPluginSelections;
  /**
   * Global defaults this workspace turns off for all its chats (see
   * {@link WorkspaceConfigFile.disabledGlobalPluginSelections}).
   */
  disabledGlobalPluginSelections?: PluginSelectionTombstones;
  scripts?: ScriptOverrides;
  effectiveScripts?: ScriptOverrides;
  hooks?: HookOverrides;
  effectiveHooks?: HookOverrides;
  activitySectionOrder?: ActivitySectionId[];
  alwaysShow?: boolean;
  /** Organization ownership; absent means Personal (CAN-2954). */
  owner?: WorkspaceOwnerBinding;
  worktreeEffective?: Record<string, WorktreeEffectiveOverrides>;
  /**
   * General external-directory bridge (see {@link WorkspaceConfigFile.externalPath}).
   * Unused by current code-workspace flows; reserved as a future default chat
   * working directory. Carried through read/write only.
   */
  externalPath?: string;
  /** Number of archived worktrees currently visible for this workspace. */
  archivedContainerCount?: number;
  /** Deletion retention for future worktree deletions; legacy null uses the default. */
  archiveRetentionDays?: number | null;
  /** Inactivity window for Auto Delete; null/absent disables it. */
  autoArchiveDays?: number | null;
  /** Whether Auto Delete also deletes the retained worktree branch locally. */
  autoArchiveDeleteBranch?: boolean;
  /** Local start-page override. Null explicitly disables the team setting. */
  startPage?: ProjectStartPage | null;
}

export interface ProjectsFile {
  version: 1;
  projects: ProjectData[];
}

export interface WorktreesFile {
  version: 1;
  worktrees: WorktreeData[];
}

/** Compact reference to a chat that contributes to a worktree badge. */
export interface WorktreeChatBadgeChatRef {
  chatId: string;
  title?: string;
  providerType?: AgentProviderType;
  /** Short last-agent-response snippet for the unread hover popover. */
  preview?: string;
  /** Set when the user marked the chat unread themselves. */
  markedUnread?: boolean;
}

/**
 * Persisted per-worktree chat badge summary, derived main-side from the
 * worktree's `ChatTabsFile` every time it is written. Lets the sidebar render
 * unread / awaiting-approval badges at startup WITHOUT hydrating every
 * worktree's full transcript into the renderer (the transcripts load lazily
 * when a worktree is opened or when live chat events arrive for it).
 */
export interface WorktreeChatBadgesSummary {
  /**
   * 2 adds {@link chatName}; main backfills older summaries once per launch.
   */
  version: 1 | 2;
  /**
   * Human name taken from the chat that started the worktree (its summary,
   * else its title), via `deriveWorktreeChatName`. Absent until a chat has a
   * name. Early access shows it as the sidebar row title.
   */
  chatName?: string;
  /** Chat tabs currently flagged unread. */
  unreadChats: WorktreeChatBadgeChatRef[];
  /** Chat tabs with a pending plan approval (`pendingPlanExit`). */
  approvalChats: WorktreeChatBadgeChatRef[];
  /**
   * True when the persisted file contains state that needs a live renderer
   * runtime to act on (scheduled sends, pending plan exits, pending ask-user
   * questions). Startup hydrates exactly these worktrees eagerly.
   */
  needsHydration: boolean;
  updatedAt: string;
}

// ---------------------------------------------------------------------------
// Multi-repo workspace types
// ---------------------------------------------------------------------------

export interface WorkspaceRepoData {
  id: string;
  name: string;
  repoPath: string;
  source?: 'local' | 'manifest';
  manifestUrl?: string;
  scripts?: ScriptOverrides;
  effectiveScripts?: ScriptOverrides;
  hooks?: HookOverrides;
  effectiveHooks?: HookOverrides;
}

/**
 * The synthetic repo id standing for "the workspace root itself", and the name
 * shown for it. Declared in `@canopy/protocol` so the web app and the shared
 * UI packages — which may not import this package — read the same value
 * instead of a hand-maintained mirror of it.
 */
export {
  WORKSPACE_ROOT_REPO_ID,
  WORKSPACE_ROOT_REPO_NAME,
} from '@canopy/protocol';
export const SINGLE_REPO_USAGE_REPO_ID = '__single_repo__';

/**
 * File-browser/file-index root id for a cowork workspace's working folder
 * (the agent cwd — managed home or attached external folder). The cowork
 * file index lists this root first with `rootKind: 'standalone'`; cwd
 * resolution (`getCwdFromFileIndex`) returns this root's own path, unlike
 * other standalone roots which resolve to their parent directory.
 */
export { COWORK_WORKSPACE_FILE_ROOT_ID } from '@canopy/protocol/ui-labels';

/**
 * Source-controlled (`canopy.json`) script map. Widened to accept the canonical
 * {@link ScriptDefinition} object form so per-script timeouts can be shared via
 * version control. Existing string-only entries remain valid.
 */
export type CanopyJsonScripts = Record<string, string | ScriptDefinition>;

/**
 * Source-controlled (`canopy.json`) repo-scoped script overrides. Accepts the
 * canonical {@link ScriptDefinition} object form alongside plain strings, plus
 * `null` to disable an inherited script.
 */
export type CanopyJsonRepoScriptOverrides = Record<
  string,
  string | ScriptDefinition | null
>;

export interface CanopyJsonRepoEntry {
  id: string;
  name: string;
  url: string;
  scripts?: CanopyJsonRepoScriptOverrides;
  hooks?: Partial<Record<HookTriggerName, HookAction[] | null>>;
}

export type CanopyJsonFile = {
  version: 1;
  scripts?: CanopyJsonScripts;
  hooks?: Partial<Record<HookTriggerName, HookAction[]>>;
  repos?: CanopyJsonRepoEntry[];
  /**
   * Source-controlled, portable plugin recommendations surfaced to teammates
   * when they open the workspace. Only `ShareablePluginRef` shapes are
   * permitted. Collections, MCP servers, local-only skills, and local-only
   * plugin marketplaces must NOT be persisted here. Local opt-outs and the
   * user's actual default plugin selections live in `WorkspaceConfigFile`.
   */
  plugins?: ShareablePluginRef[];
  /** Portable environment requirements; skill/plugin dependencies belong in `plugins`. */
  dependencies?: Array<
    Exclude<PipelineDependency, { kind: 'skill' | 'plugin' }>
  >;
  /** Source-controlled plan-detection rules. Stable ids let workspace-local
   *  config disable them. */
  planDetection?: CanopyJsonPlanDetection;
  /** Source-controlled project start page. */
  startPage?: ProjectStartPage;
  /**
   * Source-controlled tool-approval defaults and rules. `defaultMode` may
   * only de-escalate to `'ask'` or `'auto'` — the literal `'full-access'` is
   * silently dropped at parse time (non-escalation invariant) so a
   * repo-committed file can never grant blanket auto-approval. Parsed rules
   * always have `origin: 'canopy-json'` regardless of the source JSON.
   */
  approvals?: {
    defaultMode?: Extract<ApprovalMode, 'ask' | 'auto'>;
    rules?: ApprovalRule[];
  };
} & Record<string, unknown>;

export interface MultiRepoWorkspaceData {
  privateMemory?: boolean;
  privateMemoryManagedBy?: 'organization';
  id: string;
  name: string;
  color: string;
  repos: WorkspaceRepoData[];
  worktrees: WorktreeData[];
  collapsed: boolean;
  order: number;
  /** User pin within the top-level Projects section. */
  pinned?: boolean;
  /** Ordering mode for this workspace's worktree rows. */
  itemSortMode?: SidebarSortMode;
  defaultPluginSelections?: ChatTabPluginSelections;
  /**
   * Global defaults this workspace turns off for all its chats (see
   * {@link WorkspaceConfigFile.disabledGlobalPluginSelections}).
   */
  disabledGlobalPluginSelections?: PluginSelectionTombstones;
  sourceRepoPath?: string;
  scripts?: ScriptOverrides;
  effectiveScripts?: ScriptOverrides;
  hooks?: HookOverrides;
  effectiveHooks?: HookOverrides;
  suppressedRepoIds?: string[];
  activitySectionOrder?: ActivitySectionId[];
  alwaysShow?: boolean;
  /** Organization ownership; absent means Personal (CAN-2954). */
  owner?: WorkspaceOwnerBinding;
  worktreeEffective?: Record<string, WorktreeEffectiveOverrides>;
  /**
   * Marks a multi-repo workspace as a transient, local-only container created
   * by the adhoc multi-repo combine flow. Temporary workspaces are never
   * persisted into source-controlled `canopy.json`; the flag must round-trip
   * through `MultiRepoSidebarItem` and `WorkspaceConfigFile`. Missing means
   * `false`; the persistence layer is responsible for normalizing.
   */
  temporary?: boolean;
  temporarySourceWorkspaceIds?: string[];
  temporaryRepoIdentityKeys?: string[];
  /**
   * General external-directory bridge (see {@link WorkspaceConfigFile.externalPath}).
   * Unused by current multi-repo flows; reserved as a future default chat
   * working directory. Carried through read/write only.
   */
  externalPath?: string;
  /** Number of archived worktrees currently visible for this workspace. */
  archivedContainerCount?: number;
  /** Deletion retention for future worktree deletions; legacy null uses the default. */
  archiveRetentionDays?: number | null;
  /** Inactivity window for Auto Delete; null/absent disables it. */
  autoArchiveDays?: number | null;
  /** Whether Auto Delete also deletes retained worktree branches locally. */
  autoArchiveDeleteBranch?: boolean;
  /** Local start-page override. Null explicitly disables the team setting. */
  startPage?: ProjectStartPage | null;
}

/**
 * Cowork workspace: a plain non-git folder (Canopy-managed home or attached
 * external folder). Deliberately has NO `worktrees`, `repos`, or `repoPath` —
 * git-assuming consumers must narrow on `type` instead of null-checking.
 */
export interface CoworkWorkspaceData {
  privateMemory?: boolean;
  privateMemoryManagedBy?: 'organization';
  id: string;
  name: string;
  color: string;
  collapsed: boolean;
  order: number;
  /** User pin within the top-level Projects section. */
  pinned?: boolean;
  /** Ordering mode for this workspace's Work Entry rows. */
  itemSortMode?: SidebarSortMode;
  /** Absolute path of an attached external folder; absent = managed home. */
  externalPath?: string;
  defaultPluginSelections?: ChatTabPluginSelections;
  /**
   * Global defaults this workspace turns off for all its chats (see
   * {@link WorkspaceConfigFile.disabledGlobalPluginSelections}).
   */
  disabledGlobalPluginSelections?: PluginSelectionTombstones;
  /** Durable idempotency key for the first public-template publication. */
  sharedTemplatePublicationKey?: string;
  sharedTemplateExternalId?: string;
  sharedTemplateContentHash?: string;
  installedFromTemplateExternalId?: string;
  installedFromTemplateContentHash?: string;
  /** Curated Blueprint seed provenance. Unlike installs, this is reusable. */
  seededFromBlueprintExternalId?: string;
  cowork?: CoworkWorkspaceSettings;
  alwaysShow?: boolean;
  /** Organization ownership; absent means Personal (CAN-2954). */
  owner?: WorkspaceOwnerBinding;
  /** Number of live (non-archived) work entries in this workspace. */
  workEntryCount?: number;
  /** Latest persisted activity across the workspace's live Work Entries. */
  lastActivityAt?: string;
  /** Number of archived work entries currently visible for this workspace. */
  archivedContainerCount?: number;
  /** Deletion retention for future work-entry deletions; legacy null uses the default. */
  archiveRetentionDays?: number | null;
  /** Inactivity window for Auto Delete; null/absent disables it. */
  autoArchiveDays?: number | null;
}

export type SingleRepoSidebarItem = ProjectData & { type: 'single-repo' };
export type MultiRepoSidebarItem = MultiRepoWorkspaceData & {
  type: 'multi-repo';
};
export type CoworkSidebarItem = CoworkWorkspaceData & { type: 'cowork' };
export type SidebarItem =
  | SingleRepoSidebarItem
  | MultiRepoSidebarItem
  | CoworkSidebarItem;

