export interface WorkspaceConfigFile {
  privateMemory?: boolean;
  privateMemoryManagedBy?: 'organization';
  personalCatalogId?: string;
  /**
   * The workspace's cloud project identity (CAN-5190): one record for
   * Personal and organization projects, valid only under its account. Main
   * owns it: only the cloud project binding writes it, and every other config
   * write keeps what is on disk.
   */
  cloudBinding?: CloudProjectBinding;
  version: 1;
  type: WorkspaceType;
  /** Organization ownership; absent means Personal. */
  owner?: WorkspaceOwnerBinding;
  /**
   * Conversion record (CAN-3415). Like `owner`, only the ownership writer
   * changes it; ordinary config writes keep what is on disk.
   */
  ownershipTransfer?: WorkspaceOwnershipTransfer;
  /** Historical binding only; ordinary config writes preserve it. */
  detachedOwner?: WorkspaceDetachedOwner;
  repoPath?: string;
  repos: WorkspaceRepoData[];
  /** Ordering mode for the workspace's child rows. Missing means recency. */
  itemSortMode?: SidebarSortMode;
  /**
   * General external-directory bridge: absolute path of a user-provided
   * external directory. For cowork workspaces this is the working folder and
   * `.{brand}/` root — absent means the managed home at
   * `workspaces/{id}/home/`. Reserved for single-repo/multi-repo workspaces
   * as a future default chat working directory; not consumed by code-workspace
   * runtime flows today. Normalized/persisted for all workspace types.
   */
  externalPath?: string;
  /** Cowork only: cowork feature settings. */
  cowork?: CoworkWorkspaceSettings;
  /**
   * Project defaults: inherited live by every chat in the workspace (existing
   * and new) from its next turn, never copied into chats. A chat can turn one
   * off through its own `disabledGlobalPluginSelections` tombstones.
   */
  defaultPluginSelections?: ChatTabPluginSelections;
  /** Client-held identity of this workspace's public template share. */
  sharedTemplateExternalId?: string;
  /** Durable idempotency key for the first public-template publication. */
  sharedTemplatePublicationKey?: string;
  /** Opaque server hash stored verbatim after publish or republish. */
  sharedTemplateContentHash?: string;
  /** Source share identity for a workspace installed from a public template. */
  installedFromTemplateExternalId?: string;
  /** Content hash stamped only after the source template is fully applied. */
  installedFromTemplateContentHash?: string;
  seededFromBlueprintExternalId?: string;
  /**
   * Global default plugins suppressed for every chat in this workspace. See
   * {@link PluginSelectionTombstones}.
   */
  disabledGlobalPluginSelections?: PluginSelectionTombstones;
  sourceRepoPath?: string;
  scripts?: ScriptOverrides;
  hooks?: HookOverrides;
  suppressedRepoIds?: string[];
  alwaysShow?: boolean;
  /**
   * Canonical {@link getShareablePluginRefKey} strings the user has dismissed
   * from the source-controlled `canopy.json.plugins` recommendation prompt.
   * Recommendations whose key appears here are silenced for this workspace
   * (the inspector still surfaces them as `optedOut`, but the prompt does not
   * resurface them automatically).
   */
  recommendedPluginOptOutKeys?: string[];
  /**
   * Mirrors {@link MultiRepoWorkspaceData.temporary} on the persisted config
   * file. Only valid on multi-repo workspaces — single-repo configs must
   * never persist this flag. Missing means `false`; the persistence layer
   * is responsible for normalizing on read/write.
   */
  temporary?: boolean;
  temporarySourceWorkspaceIds?: string[];
  temporaryRepoIdentityKeys?: string[];
  planDetection?: WorkspacePlanDetectionConfig;
  /** Deletion retention for future container deletions; legacy null uses the default. */
  archiveRetentionDays?: number | null;
  /** Inactivity window for Auto Delete; null/absent disables it. */
  autoArchiveDays?: number | null;
  /** Code workspaces only: delete local branches during Auto Delete. */
  autoArchiveDeleteBranch?: boolean;
  /** Code projects only. Undefined inherits source; null explicitly disables it. */
  startPage?: ProjectStartPage | null;
}

