  /**
   * Delete without retention only when main confirms the worktree path is
   * missing. A present path keeps the normal retention window.
   */
  deleteWithoutRetentionIfMissing?: boolean;
  /** Remaining worktree ids in the order to persist after this archive. */
  remainingWorktreeOrder?: string[];
  /** Persisted survivor order observed before asynchronous archive cleanup. */
