  worktreeId: string;
  chatId?: string;
  pluginSelections?: ChatTabPluginSelections;
  providerType?: AgentProviderType;
  /**
   * For multi-repo workspaces: scope discovery to a specific child repo's
   * checkout. `WORKSPACE_ROOT_REPO_ID` and `undefined` resolve to the
   * workspace worktree root. Project-level slash commands and skills are
   * resolved from the chosen working directory.
   */
  selectedRepoId?: string;
