  readToolOutput(req: ChatToolOutputRequest): Promise<ChatToolOutputResponse>;
  cancelToolOutput(req: ChatToolOutputCancelRequest): Promise<void>;
  /** Read one raw byte range of a promoted visual, base64 encoded. */
  readVisual(req: ChatVisualReadRequest): Promise<ChatVisualReadResult>;
  /** Submit one validated, idempotent user-intent command. */
  command(req: ChatCommandRequest): Promise<ChatCommandResult>;
  /** Subscribe to materialized committed revisions. */
  onStateChanged(cb: (event: ChatStateChangedEvent) => void): () => void;
  /** Replace this window's declaration of the scopes it tracks. */
  setStateScopes(declaration: ChatStateScopesDeclaration): Promise<void>;
  /** Replace this window's declaration of the chats it shows. */
  setInterest(declaration: ChatInterestDeclaration): Promise<void>;
  sendMessage(req: ChatSendMessageRequest): Promise<ChatSendMessageResult>;
  editQueuedMessage(req: ChatQueueEditRequest): Promise<void>;
  cancelQueuedMessage(req: ChatQueueEntryRequest): Promise<void>;
  forceQueuedMessage(req: ChatQueueEntryRequest): Promise<void>;
  setQueuedMessageEditLock(req: ChatQueueSetEditLockRequest): Promise<void>;
  getChatQueueSnapshot(
    req: ChatQueueSnapshotRequest,
  ): Promise<ChatQueueUpdatedEvent[]>;
  onChatQueueUpdated(cb: (event: ChatQueueUpdatedEvent) => void): () => void;
  cancel(req: ChatCancelRequest): Promise<ChatCancelResult>;
  /** The live session's context-window breakdown; null without one. */
