// Tool-approval prompt types
// ---------------------------------------------------------------------------

export {
  APPROVAL_FILE_CHANGE_MAX_CHARS,
  type ApprovalFileChange,
  type ApprovalPromptDecision,
  type ApprovalRequestDetails,
} from '@canopy/protocol/approvals';

/** This value is never part of ApprovalPromptDecision or any persisted event. */
export interface ApprovalSecretInputRequest {
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  bindingId: string;
  secret: string;
  /**
   * The `policyRevision` of the card being answered (CAN-4129). A secret is
   * the card's allow, so it needs the current revision too.
   */
  policyRevision?: number;
}

export interface ApprovalRequestEvent {
  secretInput?: SecretInputApprovalPrompt;
  /** Omitted by older chat hosts. Non-chat requests have their own UI owner. */
  surface?: 'chat' | 'non-chat';
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  /** Approval-only runtimes may be evaluated before general chat registration. */
  provider: AgentProviderType | 'cursor';
  /** Provider-supplied or derived title for the approval card. */
  title: string;
  description?: string;
  details: ApprovalRequestDetails;
  /** Pre-computed rule candidate for the prompt's "always" buttons. */
  suggestedTarget?: ApprovalRuleTarget;
  toolUseId?: string;
  /**
   * Set when the tool call that triggered this approval originated from a
   * subagent rather than the chat's root agent turn. Carries the
   * provider-specific subagent identifier (Claude's SDK `agentID`, or the
   * Codex subagent's non-root `threadId`) so the renderer can attribute the
   * request. Absent when the request came from the root turn, or when the
   * provider path cannot distinguish (see `docs/tool-approvals.md`).
   */
  subagentId?: string;
  /** Internal identity for the durable turn-timer pause held by this prompt. */
  timerPauseOwnerId?: string;
  /**
   * The approval policy revision this card was shown under (CAN-4129).
   * Main always sets it; send it back with an allow. Optional only so
   * cards persisted by older builds still parse.
   */
  policyRevision?: number;
}

export interface ApprovalRespondRequest {
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  decision: ApprovalPromptDecision;
  /**
   * The `policyRevision` of the card being answered (CAN-4129). An allow
   * without the current revision is refused.
   */
  policyRevision?: number;
}

export interface ApprovalDismissRequest {
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
}

export interface ApprovalCancelledEvent {
  requestId: string;
}

/**
 * A pending approval prompt was resolved by the main process without the user
 * answering it, because they widened the chat's approval mode while the card
 * was on screen and the new mode would not have asked (CAN-3083).
 *
 * Deliberately *not* `approval:cancelled`: both producers of that event reject
 * the pending promise, so the provider is told the tool was denied. Reusing it
 * here would contradict what the provider was actually told.
 *
 * Carries the full chat identity so the renderer can place the resolution on
 * the right tab even if it has already dropped its own pending entry.
 *
 * A mode change may only ever *release* a pending prompt. It never auto-denies,
 * so there is no denying counterpart to this event.
 */
export interface ApprovalAutoResolvedEvent {
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  reason: 'mode-change';
  mode: ApprovalMode;
  previousMode?: ApprovalMode;
  /**
   * The system message main already committed for this resolution. Main mints
   * the id, so grafting it is idempotent: a later hydrate that already carries
   * the message is a no-op. Absent when the batch committed no message.
   */
  resolutionMessage?: PersistedChatMessage;
}

export interface ApprovalModeSetRequest {
  projectId: string;
  worktreeId: string;
  chatId: string;
  mode: ApprovalMode;
  previousMode?: ApprovalMode;
}

/**
 * Requests the effective approval-mode default for a project/workspace,
 * resolved server-side through the same chain as
 * `resolveApprovalMode`/`surfaceForChat` minus the tab/hook tiers (those only
 * exist once a specific chat turn is being sent). Used by the renderer to
 * seed a new chat tab's `ApprovalModePicker` and as the send-time fallback
 * when a tab has no explicit `approvalMode` override.
 */
export interface ApprovalResolvedDefaultRequest {
  projectId: string;
  /**
   * Scope key for synthetic Code Review / Plan Explore chat projects. The
   * main process uses it to resolve the real owning workspace.
   */
  worktreeId?: string;
}

export interface ApprovalRulesListRequest {
  workspaceId?: string;
}

export interface ApprovalRulesListResponse {
  project: ApprovalRule[];
  global: ApprovalRule[];
}

export interface ApprovalRuleAddRequest {
  scope: 'project' | 'global';
  workspaceId?: string;
  rule: ApprovalRule;
}

export interface ApprovalRuleRemoveRequest {
  scope: 'project' | 'global';
  workspaceId?: string;
  ruleId: string;
}

export interface ApprovalRuleAddedEvent {
  projectId: string;
  worktreeId: string;
  chatId: string;
  rule: ApprovalRule;
}

/**
 * Persisted pending tool-approval prompt for a chat tab. Stored at the
 * `ChatTabsFile` level (see `pendingApprovals`), mirroring
 * `PersistedPendingQuestion`.
 */
export interface PersistedPendingApproval {
  requestId: string;
  chatId: string;
  event: ApprovalRequestEvent;
}

export interface ApprovalsApi {
  respond(req: ApprovalRespondRequest): Promise<boolean>;
  respondSecretInput(req: ApprovalSecretInputRequest): Promise<boolean>;
  dismiss(req: ApprovalDismissRequest): Promise<boolean>;
  pendingRequests(): Promise<ApprovalRequestEvent[]>;
  setMode(req: ApprovalModeSetRequest): Promise<void>;
  getResolvedDefault(
    req: ApprovalResolvedDefaultRequest,
  ): Promise<ApprovalMode>;
  listRules(req: ApprovalRulesListRequest): Promise<ApprovalRulesListResponse>;
  addRule(req: ApprovalRuleAddRequest): Promise<void>;
  removeRule(req: ApprovalRuleRemoveRequest): Promise<void>;
  onRequest(cb: (event: ApprovalRequestEvent) => void): () => void;
  onCancelled(cb: (event: ApprovalCancelledEvent) => void): () => void;
  onAutoResolved(cb: (event: ApprovalAutoResolvedEvent) => void): () => void;
  onRuleAdded(cb: (event: ApprovalRuleAddedEvent) => void): () => void;
}

/** The Cursor account the managed runtime is signed in as. */
export interface CursorAccount {
  /** Empty when the CLI reports no email, or one that is not a plain address. */
  email: string;
}
/**
 * What the panel showed when the user acted. `change` may sign the shared
 * credential store out; `sign-in` promises it will not, so the main process
 * refuses rather than signing out when the runtime disagrees.
 */
export type CursorAccountIntent = 'change' | 'sign-in';
export interface CursorConnectionStatus {
  supported: boolean;
  installed: boolean;
  enabled: boolean;
  version: string;
  phase:
    | 'idle'
    | 'downloading'
    | 'verifying'
    | 'installing'
    | 'signing-out'
    | 'signing-in'
    | 'connected';
  percent?: number;
  /** Pinned archive size in bytes, present when this platform has an artifact. */
  archiveBytes?: number;
  /**
   * Present only on results that probed the CLI (Connect, Change account);
   * the cheap status read never runs the runtime.
   */
  account?: CursorAccount | null;
}
export interface CursorConnectionApi {
  listModels(): Promise<CursorModelEntry[]>;
  status(): Promise<CursorConnectionStatus>;
  connect(): Promise<CursorConnectionStatus>;
  cancel(): Promise<void>;
  disconnect(): Promise<void>;
  /** Verifies the installed runtime and reads its signed-in account, if any. */
  account(): Promise<CursorAccount | null>;
  /**
   * Runs the same browser sign-in as Connect. `change` signs the shared Cursor
   * credential store out first; `sign-in` — used after a cancelled change —
   * takes nothing away.
   */
  changeAccount(intent: CursorAccountIntent): Promise<CursorConnectionStatus>;
  onProgress(callback: (status: CursorConnectionStatus) => void): () => void;
}

export interface CursorApprovalCheckResult {
  outcome: 'allowed' | 'denied' | 'cancelled' | 'error';
  filePath?: string;
  message?: string;
  hookObserved: boolean;
  processExited: boolean;
}

export interface CursorApprovalCheckApi {
  available(): Promise<boolean>;
  run(binaryPath: string): Promise<CursorApprovalCheckResult>;
  cancel(): Promise<void>;
}

