export interface McpQuestion extends PortalQuestionControl {
  id?: string;
  header?: string;
  question: string;
  options: string[];
  multiSelect?: boolean;
  optionDescriptions?: string[];
  allowOther?: boolean;
  secret?: boolean;
  keepTextOnPick?: boolean;
}

export interface McpQuestionAnswer {
  questionId?: string;
  question: string;
  selectedOptions: string[];
  freeformText?: string;
  /**
   * Who settled the question, stamped by Electron main when it hands the
   * answer to the waiting tool; client input never sets it. `person` only
   * for the window's question card, the window's renderer relay or a Portal
   * session of the signed-in user; every other answer is `agent`.
   */
  answeredBy?: 'person' | 'agent';
}

export interface McpAskUserEvent {
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  questions: McpQuestion[];
  /**
   * Optional deterministic correlation id used by providers that can supply
   * a `tool_use` id alongside the IPC event. When present, the renderer
   * copies this onto the stored `PendingQuestion` so it can match the card
   * to the eventual `tool_use` block by exact id. When set, it must equal
   * that block's id: a record with a different id never falls back to the
   * ordered-question-text match, so its card would not settle.
   *
   * Notes:
   *  - Codex paths (dynamic `canopy_ask_user_question` and built-in
   *    `request_user_input`) MUST set this to `codex-<callId>` /
   *    `codex-<itemId>` respectively.
   *  - Claude MCP path omits this because the Claude Agent SDK does not
   *    expose `tool_use_id` inside the `tool()` handler's `extra` arg.
   *  - The IPC `requestId` remains the authoritative lookup key; do not
   *    back-derive `toolUseId` from `requestId`.
   */
  toolUseId?: string;
}

export interface McpAnswerUserRequest {
  requestId: string;
  answers: McpQuestionAnswer[];
}

export interface McpAnswerUserResponse {
  accepted: boolean;
}

export interface McpDismissUserRequest {
  requestId: string;
}

export interface McpExpireAskUserEvent {
  requestId: string;
}

