// Plan mode types
// ---------------------------------------------------------------------------

export interface PlanExitRequestEvent {
  /** Reject completions from a turn superseded by a later user message. */
  turnUserMessageId?: string;
  requestId: string;
  projectId: string;
  worktreeId: string;
  chatId: string;
  toolInput: Record<string, unknown>;
  source?: AgentProviderType;
  reviewMode?: 'manual' | 'proposal';
  planId?: string;
  revisionNumber?: number;
  pendingSystemInstructions?: PendingSystemInstruction[];
}

export interface PlanExitApproveRequest {
  requestId: string;
}

export interface PlanExitDenyRequest {
  requestId: string;
}

export interface PendingSystemInstruction {
  id: string;
  text: string;
}

/**
 * A tracked plan sent with a chat message as its active plan, plus the older
 * revision the user was viewing when that differs from the latest.
 */
export interface ChatActivePlanContext {
  planId: string;
  viewedRevisionNumber?: number;
}

/**
 * Why a plan-file instruction is built: `authored-plan` for a plan the agent
 * itself prepared (ExitPlanMode, Codex plan tracking), `active-plan` for the
 * plan the user has open while chatting.
 */
export type PlanFileInstructionPurpose = 'authored-plan' | 'active-plan';

export interface PreparePlanFileSystemInstructionRequest {
  projectId: string;
  worktreeId: string;
  planId: string;
  /** Defaults to `authored-plan`. */
  purpose?: PlanFileInstructionPurpose;
  /** An older revision on screen (`active-plan` only). */
  viewedRevisionNumber?: number;
}

export interface PreparePlanFileSystemInstructionResponse {
  instruction?: PendingSystemInstruction;
}

export interface TrackedPlanRevisionData {
  /** Canonical proposal event identity, retained to reconcile projection retries. */
  proposalRequestId?: string;
  revisionNumber: number;
  content: string;
  source: TrackedPlanSource;
  reviewStatus: TrackedPlanReviewStatus;
  createdAt: string;
  approvedAt?: string;
  dismissedAt?: string;
}

/**
 * Sync lifecycle of a tracked plan's cloud copy. Local-only metadata; not part
 * of any shared-plan DTO.
 */
export type TrackedPlanShareSyncStatus =
  | 'pending'
  | 'syncing'
  | 'synced'
  | 'error';

/**
 * Link/sync metadata persisted on a local tracked plan so the local copy can
 * link to and keep its Canopy Cloud server copy revised. Stored locally only
 * (never sent as part of a shared-plan DTO).
 */
export interface TrackedPlanShareState {
  /** Canopy Cloud server id the plan was shared to. */
  serverId: string;
  /** Server-generated external id of the shared-plan copy. */
  remoteId: string;
  shareScope: 'private' | 'team' | 'organization';
  /** Team target id for team-owned shares, retained for 404 recreate recovery. */
  teamId?: string;
  /** Organization target id for organization-owned shares, retained for 404 recreate recovery. */
  organizationId?: string;
  syncStatus: TrackedPlanShareSyncStatus;
  lastSyncedAt?: string;
  lastSyncedLocalRevisionNumber?: number;
  lastSyncedRemoteRevisionNumber?: number;
  lastSyncedSnapshotHash?: string;
  lastSyncError?: string;
}

export interface TrackedPlanData {
  id: string;
  projectId: string;
  worktreeId: string;
  source: TrackedPlanSource;
  /** Canonical chat identity for recovering implicit Cursor proposal projection. */
  proposalChatId?: string;
  title: string;
  content: string;
  reviewStatus: TrackedPlanReviewStatus;
  createdAt: string;
  updatedAt: string;
  latestRevisionNumber: number;
  approvedAt?: string;
  dismissedAt?: string;
  revisions: TrackedPlanRevisionData[];
  linkedExecutionIds: string[];
  hidden?: boolean;
  /** Generated, derived diagram artifacts keyed by source revision. */
  diagrams?: PlanDiagramArtifacts;
  /** Persistent comment threads on the plan document. */
  commentThreads?: PlanCommentThread[];
  /** Which actor produced the latest content. */
  lastEditSource?: PlanEditSource;
  /**
   * Repo-relative path of the originating file for `imported`/`detected`
   * plans. Absent for agent/pipeline plans. For `detected` plans this is half
   * of the dedup key (`sourceRepoId` + `sourceFilePath`).
   */
  sourceFilePath?: string;
  /**
   * Repo id the source file lives in (`WORKSPACE_ROOT_REPO_ID` for the
   * workspace-root repo). Absent for agent/pipeline plans.
   */
  sourceRepoId?: string;
  /**
   * Cloud share link/sync metadata. Absent until the plan is shared.
   * Backward-compatible optional data: plan JSON files written before this
   * field existed (and `TrackedPlansFile.version` 1) must still load.
   */
  share?: TrackedPlanShareState;
}

export interface TrackedPlansFile {
  version: 1;
  plans: TrackedPlanData[];
}

export interface SaveTrackedPlanCommentsRequest {
  projectId: string;
  worktreeId: string;
  planId: string;
  commentThreads: PlanCommentThread[];
}

export interface GenerateTrackedPlanDiagramsRequest {
  projectId: string;
  worktreeId: string;
  planId: string;
}

export type DeleteTrackedPlanRequest = TrackedPlanGetRequest;

export interface ImportTrackedPlanRequest {
  projectId: string;
  worktreeId: string;
  /**
   * Optional source path for non-UI callers. Agent-facing callers must provide
   * a worktree-relative path; absolute paths are only accepted by the native
   * Browse dialog branch. When omitted, the desktop import handler opens the
   * native file picker.
   */
  filePath?: string;
  /**
   * Repo the source file lives in. `WORKSPACE_ROOT_REPO_ID` and the detection
   * sentinel `'__worktree__'` both resolve to the worktree root. Non-dialog
   * imports must provide this field. Absolute `filePath` values ignore it.
   */
  repoId?: string;
  initiationSource?: UsageInitiationSource;
}

export interface ImportTrackedPlanResponse {
  plan: TrackedPlanData | null;
  /**
   * Canopy-managed JSON file that persists tracked plans for the target
   * worktree.
   */
  trackedPlanFilePath: string;
}

export type DetectedPlanStatus = 'detected' | 'dismissed' | 'imported';

export interface DetectedPlanEntry {
  id: string;
  sourceRepoId: string;
  /** Repo-relative POSIX path. With sourceRepoId this is the dedup key. */
  sourceFilePath: string;
  status: DetectedPlanStatus;
  /** Banner acknowledgement, independent of status. */
  bannerSeen: boolean;
  /** Chat tab the detection originated in. */
  detectedInChatId: string;
  detectedAt: string;
  /** Set once imported; links to the created tracked plan. */
  importedPlanId?: string;
}

export interface DetectedPlansFile {
  version: 1;
  entries: DetectedPlanEntry[];
}

export interface DetectedPlansListRequest {
  projectId: string;
  worktreeId: string;
}

export interface DetectedPlansScanRequest extends DetectedPlansListRequest {
  chatId: string;
  candidatePaths: string[];
}

export interface DetectedPlansScanResponse {
  entries: DetectedPlanEntry[];
  newlyDetected: DetectedPlanEntry[];
}

export interface DetectedPlanUpdateRequest extends DetectedPlansListRequest {
  entryId: string;
  status?: DetectedPlanStatus;
  bannerSeen?: boolean;
  importedPlanId?: string;
}

export interface DetectedPlansUpdatedEvent {
  projectId: string;
  worktreeId: string;
  entries: DetectedPlanEntry[];
}

/**
 * Renderer ⇄ main request to pull a shared plan's latest comment threads from
 * Canopy Cloud and merge web-authored comments back into the local store
 * (CAN-393). Handled on `IPC_CHANNELS.trackedPlansRefreshComments`.
 */
export type RefreshTrackedPlanCommentsRequest = TrackedPlanGetRequest;

/**
 * Renderer → main lease telling the plan-file sync service that a plan view is
 * (or is no longer) visible, so the plan's working file is checked for agent
 * edits while someone looks at it. `consumerId` identifies one view within
 * the sending window. Handled on `IPC_CHANNELS.trackedPlansFileVisibility`.
 */
export interface TrackedPlanFileVisibilityRequest {
  projectId: string;
  worktreeId: string;
  planId: string;
  consumerId: string;
  visible: boolean;
}

/**
 * Renderer ⇄ main request to share a tracked plan to Canopy Cloud (and to
 * re-sync the cloud copy on subsequent calls). The handler that listens on
 * `IPC_CHANNELS.trackedPlansShare` is implemented in the Backend plan.
 */
export interface ShareTrackedPlanRequest extends TrackedPlanGetRequest {
  shareScope?: 'private' | 'team' | 'organization';
  teamId?: string;
  organizationId?: string;
}

/**
 * Renderer ⇄ main request to stop sharing a tracked plan (CAN-5904): delete
 * the cloud copy and clear the local `share`. Handled on
 * `IPC_CHANNELS.trackedPlansUnshare`; the answer is a
 * `ShareOperationResult<TrackedPlanData | null>` whose plan has no `share`.
 */
export type UnshareTrackedPlanRequest = TrackedPlanGetRequest;

export interface ShareTrackedPlanResponse {
  /** The updated local plan (now carrying `share` metadata), or null. */
  plan: TrackedPlanData | null;
}

/**
 * Renderer ⇄ main request to explicitly share a finished agent session as a
 * run to Canopy Cloud (CAN-395). Handled on `IPC_CHANNELS.runsShare`. The
 * explicit click is its own consent: sharing proceeds even when ambient
 * telemetry sync is Off, ingesting the referenced turns/plans on demand at
 * USER/owner scope first. Importable snapshot transfer uses session exports.
 */
export interface ShareRunRequest {
  projectId: string;
  worktreeId: string;
  chatId: string;
  shareScope?: RunShareScope;
  teamId?: string;
  organizationId?: string;
  /** Main-process background refreshes preserve the server-side audience. */
  preserveExistingOwner?: boolean;
}

/**
 * Why a session cannot be shared. Distinguishes an expected, permanent "there
 * is nothing to share" outcome from a transport/auth failure, so the UI can
 * explain it instead of showing a generic error the user can only retry.
 *
 * `no-activity` — the session has no finished audit entries. A run is assembled
 * from observability audit data, not from the persisted transcript, so a chat
 * whose entries have aged out of the `auditRetentionDays` window can no longer
 * be shared even though its messages are still on disk.
 *
 * `blocked-by-org-policy` — an organization the user belongs to prohibits the
 * data a shared run carries (`transcripts`, or the `metadata` envelope the run
 * rows need). Run sharing deliberately bypasses the ambient sharing gate, so
 * without this it would be a one-click bypass of an org's data-sharing policy.
 * Also permanent from the user's side: only an org admin can lift it.
 */
export type ShareRunBlockedReason =
  | 'no-activity'
  | 'blocked-by-org-policy'
  /**
   * The target org lost the `teams` capability (CAN-2311). Deliberately NOT
   * folded into `blocked-by-org-policy`: that reason renders "sharing that data
   * is blocked by {org}... only an organization admin can change this", which
   * is false here. The org has no data-sharing prohibition, its subscription
   * lapsed, and the remedy is to pay rather than to change a policy setting.
   */
  | 'blocked-by-org-billing';

/**
 * Result of a run share. `externalId` is the created `SharedRun.externalId`;
 * `null` when the session could not be shared, in which case `reason` says why.
 */
export interface ShareRunResponse {
  externalId: string | null;
  /** Set whenever `externalId` is `null`. */
  reason?: ShareRunBlockedReason;
  /** Retention window governing `no-activity`, for the explanation copy. */
  auditRetentionDays?: number;
  /**
   * Names of the organizations behind a `blocked-by-org-policy` or
   * `blocked-by-org-billing` reason, so the UI can say who blocked it instead
   * of showing an unattributable refusal.
   */
  blockedByOrganizationNames?: string[];
}

/**
 * Renderer ⇄ main request asking whether a session can be shared at all,
 * handled on `IPC_CHANNELS.runsShareEligibility`. The share modal probes this
 * on open so an unshareable session is explained up front rather than after the
 * user picks an audience and clicks Share.
 */
export interface ShareRunEligibilityRequest {
  projectId: string;
  worktreeId: string;
  chatId: string;
}

/** Result of an eligibility probe. `reason` is set when `shareable` is false. */
export interface ShareRunEligibilityResponse {
  shareable: boolean;
  reason?: ShareRunBlockedReason;
  auditRetentionDays: number;
  /**
   * Names of the organizations behind a `blocked-by-org-policy` reason. Lets
   * the Share affordance render disabled with an explanation naming the org
   * rather than a generic "unavailable".
   */
  blockedByOrganizationNames?: string[];
}

/**
 * Renderer ⇄ main request to unshare (delete) a previously shared run
 * (CAN-395). Handled on `IPC_CHANNELS.runsUnshare`. Keyed by the session
 * identity so main recomputes the deterministic idempotency key rather than
 * trusting a locally-persisted `externalId` that may be stale.
 */
export interface UnshareRunRequest {
  projectId: string;
  worktreeId: string;
  chatId: string;
}

/** Result of an unshare. `unshared` is true when the grant was removed. */
export interface UnshareRunResponse {
  unshared: boolean;
}

// ---------------------------------------------------------------------------
// Shared-run comments (CAN-397).
//
// Comments are server-authoritative: there is no desktop-local comment store
// and no merge algorithm. Every one of these requests is a thin pass-through to
// the Canopy Cloud REST surface, and every response is the full authoritative
// `SharedRunDetail` the server returned.
// ---------------------------------------------------------------------------

/** Identifies the shared chat a comment operation targets. */
export interface RunCommentSessionRef {
  projectId: string;
  worktreeId: string;
  chatId: string;
}

/** Request for `IPC_CHANNELS.runsCommentsList`. */
export type ListRunCommentsRequest = RunCommentSessionRef;

/**
 * Result of a comment read. `detail` is `null` when the chat is not shared, the
 * grant is gone server-side, or the connected Canopy Cloud does not advertise
 * `run-comments-v1` — all of which degrade to "no comments" rather than an
 * error, so an older server never breaks the chat UI.
 */
export interface ListRunCommentsResponse {
  detail: SharedRunDetail | null;
  /** Comment revision the user has already seen for this run, if any. */
  lastSeenCommentRevision: number;
}

/** Request for `IPC_CHANNELS.runsCommentsCreate`. */
export interface CreateRunCommentThreadRequest extends RunCommentSessionRef {
  body: string;
  /** Defaults to a whole-run thread when omitted. */
  anchor?: SharedRunCommentAnchor;
}

/** Request for `IPC_CHANNELS.runsCommentsReply`. */
export interface ReplyRunCommentThreadRequest extends RunCommentSessionRef {
  threadId: string;
  body: string;
}

/** Request for `IPC_CHANNELS.runsCommentsSetStatus`. */
export interface SetRunCommentThreadStatusRequest extends RunCommentSessionRef {
  threadId: string;
  status: SharedRunCommentThreadStatus;
}

/** Result of any comment mutation: the fresh server-authoritative detail. */
export interface RunCommentMutationResponse {
  detail: SharedRunDetail;
}

/** Request for `IPC_CHANNELS.runsCommentsMarkSeen`. */
export interface MarkRunCommentsSeenRequest extends RunCommentSessionRef {
  /** Revision the user has now seen; clamped to the last polled value. */
  commentRevision: number;
}

/** Result of marking comments seen: the cleared unread state. */
export interface MarkRunCommentsSeenResponse {
  lastSeenCommentRevision: number;
  unreadCommentCount: number;
}

/**
 * Payload of `IPC_CHANNELS.runsCommentsUpdated`, emitted by the main-process
 * poller when a shared run's `commentRevision` advances past the last-seen
 * value for that run.
 */
export interface RunCommentsUpdatedEvent extends RunCommentSessionRef {
  /** `SharedRun.externalId` of the run whose comments changed. */
  externalId: string;
  /** Server comment revision observed on this poll. */
  commentRevision: number;
  /** Revision the user had already seen before this poll. */
  lastSeenCommentRevision: number;
  /** Comments added since the last seen revision, for the unread badge. */
  unreadCommentCount: number;
  /**
   * Whether every new comment was authored by the signed-in user (e.g. a reply
   * the user just posted from the web). Consumers must not notify in that case.
   */
  ownCommentsOnly: boolean;
}

/** Preload API surface for sharing finished agent sessions as runs (CAN-395). */
export interface RunsApi {
  share(
    request: ShareRunRequest,
  ): Promise<ShareOperationResult<ShareRunResponse>>;
  unshare(request: UnshareRunRequest): Promise<UnshareRunResponse>;
  /** Whether this session has shareable activity, probed before sharing. */
  checkShareEligibility(
    request: ShareRunEligibilityRequest,
  ): Promise<ShareRunEligibilityResponse>;
  /** Read the server-authoritative comment threads for a shared chat. */
  listComments(
    request: ListRunCommentsRequest,
  ): Promise<ListRunCommentsResponse>;
  createCommentThread(
    request: CreateRunCommentThreadRequest,
  ): Promise<RunCommentMutationResponse>;
  replyToCommentThread(
    request: ReplyRunCommentThreadRequest,
  ): Promise<RunCommentMutationResponse>;
  setCommentThreadStatus(
    request: SetRunCommentThreadStatusRequest,
  ): Promise<RunCommentMutationResponse>;
  markCommentsSeen(
    request: MarkRunCommentsSeenRequest,
  ): Promise<MarkRunCommentsSeenResponse>;
  onCommentsUpdated(
    callback: (event: RunCommentsUpdatedEvent) => void,
  ): () => void;
}

// ---------------------------------------------------------------------------
// Shared containers (CAN-2546).
// ---------------------------------------------------------------------------

export type SharedContainerBlockedReason =
  | 'no-cloud-account'
  | 'account-unavailable'
  | 'guest-account'
  | 'no-organization'
  | 'unsupported-capability'
  | 'sync-disabled'
  | 'sync-blocked-by-org'
  | 'not-yet-synced'
  | 'registration-failed'
  | 'anchored-to-other-organization'
  | 'insufficient-role'
  | 'blocked-by-org-billing'
  | 'github-not-ready'
  | 'external-sharing-disabled';

/**
 * Who an invite reaches. Team and Organization pick people from that scope;
 * Public takes an email address and creates a direct grant or a pending
 * invite outside the organization.
 */
export type SharedContainerInviteAudience = 'team' | 'organization' | 'public';

/** Which invite audiences the current account can use for this container. */
export type SharedContainerAudienceAvailability = Record<
  SharedContainerInviteAudience,
  boolean
>;

export interface SharedContainerLinkAvailability {
  anyone: boolean;
  organization: boolean;
}

/** Why Public is offered but not usable for this container. */
export type SharedContainerPublicAudienceBlockedReason =
  | 'external-sharing-disabled'
  | 'feature-disabled';

export interface SharedContainerTargetRequest {
  projectId: string;
  worktreeId: string;
  /**
   * Organization the container belongs to. Absent means a personal container
   * (owned by the user, not an organization), which only Public can create.
   */
  organizationId?: string;
  containerType: SharedContainerType;
  /** Audience the author picked; decides personal vs org ownership. */
  audience?: SharedContainerInviteAudience;
}

export type SharedContainerEligibilityRequest = SharedContainerTargetRequest;

/**
 * Why a worktree's Git state cannot be made shareable by a safe, ordinary
 * push. Each value maps to one concise renderer explanation; none of them
 * offers the Push to GitHub recovery action.
 */
export type SharedContainerGithubBlockedReason =
  | 'no-repositories'
  | 'missing-origin'
  | 'non-github-origin'
  | 'no-branch'
  | 'no-head'
  | 'diverged'
  | 'unavailable';

/**
 * Classified GitHub readiness for a code worktree.
 *
 * `push-required` is the ONLY state that authorizes the one-click recovery:
 * a normal, non-force `git push` of the existing HEAD to the same-named
 * `origin` branch fixes it. Everything else is `blocked` and receives
 * guidance instead of a button.
 */
export type SharedContainerGithubReadiness =
  | { status: 'ready' }
  | { status: 'push-required' }
  | { status: 'blocked'; reason: SharedContainerGithubBlockedReason };

export type SharedContainerPrepareGithubRequest = SharedContainerTargetRequest;

/**
 * Result of the one-click recovery. `failed` is a bounded, retryable
 * transport/authentication outcome: raw Git output and remote credentials
 * never reach the renderer.
 */
export type SharedContainerPrepareGithubResponse =
  | { status: 'ready' }
  | {
      status: 'blocked';
      readiness: Extract<SharedContainerGithubReadiness, { status: 'blocked' }>;
    }
  | { status: 'failed' };

export interface SharedContainerEligibilityResponse {
  eligible: boolean;
  reason?: SharedContainerBlockedReason;
  blockedByOrganizationNames?: string[];
  /** Server `Worktree.externalId`; present only after metadata sync exists. */
  serverWorktreeExternalId?: string;
  /**
   * Structured detail accompanying `reason: 'github-not-ready'`. Optional so
   * older or partial responses stay valid; consumers must treat an absent
   * value as `blocked/unavailable` rather than assuming a push can help.
   */
  githubReadiness?: SharedContainerGithubReadiness;
  /**
   * Audiences the invite modal offers for this container. Unavailable ones are
   * rendered disabled, never hidden. Absent from older main processes, which
   * the renderer reads as "Team and Organization only".
   */
  audiences?: SharedContainerAudienceAvailability;
  /** Capability-link audiences available for this container. */
  link?: SharedContainerLinkAvailability;
  /** Set when `audiences.public` is false while external sharing is offered. */
  publicBlockedReason?: SharedContainerPublicAudienceBlockedReason;
  /**
   * Organization that owns (or will own) this container. Fixed by an
   * org-owned workspace or an existing anchor; absent for a personal
   * container. The renderer sends this back as `organizationId`.
   */
  ownerOrganizationId?: string;
  /**
   * True when ownership is already fixed (org-owned workspace or existing
   * sync anchor), so the modal must not offer an organization picker.
   */
  ownerFixed?: boolean;
}

export interface SharedContainerFileScope {
  /** Legacy Cowork allowlist. Ignored for code worktrees. */
  includedPaths: string[];
  /** File opt-outs. Presence switches Cowork scopes to default-included semantics. */
  excludedPaths?: string[];
  /** Preserves a legacy Cowork allowlist after its final path is removed. */
  legacyAllowlist?: boolean;
  /** Legacy note allowlist. Retained for persisted-schema compatibility only. */
  includedNoteIds?: string[];
  /** Notes are included unless their id appears here. */
  excludedNoteIds?: string[];
  /** Legacy prompt allowlist. Retained for persisted-schema compatibility only. */
  includedPromptIds?: string[];
  /** Prompts are included unless their id appears here. */
  excludedPromptIds?: string[];
  /** Legacy run-sharing opt-in. Retained for persisted-schema compatibility only. */
  runSharingEnabled?: boolean;
  /** Run sharing is on unless this is true. */
  runSharingDisabled?: boolean;
  /** Legacy run-script allowlist. Retained for persisted-schema compatibility only. */
  includedRunScripts?: string[];
  /** Run scripts are selected by default unless their name appears here. */
  excludedRunScripts?: string[];
  /**
   * The publisher's preferred layout, which receivers reset to on every open.
   * Absent means on and not pinned yet. `pinnedAt` is set once a layout is
   * pinned; the pinned snapshot itself never leaves the main process.
   */
  preferredLayout?: SharedContainerPreferredLayoutState;
}

export interface SharedContainerPreferredLayoutState {
  enabled: boolean;
  /** ISO timestamp of the pinned layout. Absent when off or not pinned yet. */
  pinnedAt?: string;
}

/**
 * What a scope save does to the preferred layout: `keep` leaves it unchanged,
 * `pin-current` turns it on and pins the publisher's current layout, and
 * `clear` turns it off and drops the pin.
 */
export type SharedContainerPreferredLayoutRequest =
  | 'keep'
  | 'pin-current'
  | 'clear';

export interface SharedContainerSharePreview {
  containerType: SharedContainerType;
  chatCount: number;
  planCount: number;
  attachmentCount: number;
  noteCount: number;
  promptCount: number;
  notes: Array<{ id: string; title: string }>;
  prompts: Array<{ id: string; title: string }>;
  startPage: {
    label: string;
    status: 'included' | 'withheld' | 'url';
  } | null;
  repository?: { remoteUrl: string; baseCommitSha: string };
  repositories?: Array<{
    repoId: string;
    repoName: string;
    remoteUrl: string;
    baseCommitSha: string;
  }>;
  dirtyFileCount: number;
  untrackedCandidates: string[];
  untrackedCandidateCount: number;
  /** Ranked candidates selected after exclusions and artifact-budget capping. */
  defaultIncludedFilePaths?: string[];
  approvedFileScope: SharedContainerFileScope;
  /**
   * Every script name the publisher may tick for run sharing, across the
   * disclosed repositories. Sourced from the same resolver that feeds their
   * own Scripts panel, so the picker offers what they can already see rather
   * than a hard-coded pair.
   */
  availableRunScripts?: string[];
  run?: SharedContainerRevisionRunConfig;
  artifactBudget: { used: number; limit: number };
  unpushedCommitCount?: number;
  snapshotRepositoryCount?: number;
  snapshotBytes?: number;
  snapshotRepositoryNames?: string[];
  undisclosedRepositoryCount?: number;
  withheldFileCount?: number;
  withheldFilePaths?: string[];
  withheldSymlinkPaths?: string[];
  /**
   * Finalized counts from a completed capability-package analysis for this
   * scope. Absent while analysis is cold, stale, failed or empty.
   */
  capabilityPackageCounts?: SharedContainerCapabilityPackageCounts;
}

export type SharedContainerPreviewRequest = SharedContainerTargetRequest;

export interface SaveSharedContainerFileScopeRequest {
  projectId: string;
  worktreeId: string;
  includedPaths: string[];
  excludedPaths?: string[];
  legacyAllowlist?: boolean;
  includedNoteIds?: string[];
  excludedNoteIds?: string[];
  includedPromptIds?: string[];
  excludedPromptIds?: string[];
  runSharingEnabled?: boolean;
  runSharingDisabled?: boolean;
  includedRunScripts?: string[];
  excludedRunScripts?: string[];
  /** Defaults to `keep`. */
  preferredLayout?: SharedContainerPreferredLayoutRequest;
}

export interface SaveSharedContainerFileScopeResponse {
  fileScope: SharedContainerFileScope;
}

export type SharedContainerPublicationStatus =
  | 'not-published'
  | 'publishing'
  | 'published'
  | 'error';

export type SharedContainerPublicationErrorReason =
  | 'unpushed-head'
  | 'git-lfs'
  | 'undisclosable-repository'
  | 'artifact-budget'
  | 'submodule'
  | 'symlink';

export interface SharedContainerPublicationState {
  projectId: string;
  worktreeId: string;
  /** Absent for a personal container. */
  organizationId?: string;
  containerId?: string;
  containerType?: SharedContainerType;
  status: SharedContainerPublicationStatus;
  revision?: number;
  error?: string;
  errorReason?: SharedContainerPublicationErrorReason;
  updatedAt: string;
}

export interface InviteSharedContainerRequest extends SharedContainerTargetRequest {
  /** An organization member (Team/Organization) or an email address (Public). */
  recipient: SharedContainerRecipientRequestWire;
  capabilities: SharedContainerCapability[];
}

export interface SharedContainerLinkOwnerRequest {
  containerId: string;
}

export type SetSharedContainerLinkIpcRequest =
  | (SharedContainerLinkOwnerRequest & {
      /** Null turns the capability link off. */
      audience: SharedContainerLinkAudience | null;
    })
  | (Omit<SharedContainerTargetRequest, 'audience'> & {
      /** The first enable creates the owner container without an invite. */
      containerId: null;
      audience: SharedContainerLinkAudience;
    });

export interface SetSharedContainerLinkIpcResponse {
  link: SharedContainerLink | null;
  /** Present when this mutation created the first owner container. */
  container?: SharedContainerSummary;
  publicationState?: SharedContainerPublicationState;
}

export interface SharedContainerLinkTokenRequest {
  token: string;
}

export type InviteSharedContainerResponse =
  | (CreateSharedContainerGrantResponse & {
      invited: true;
      publicationState: SharedContainerPublicationState;
    })
  | {
      invited: false;
      reason: SharedContainerBlockedReason;
      blockedByOrganizationNames?: string[];
    };

export interface SearchSharedContainerMembersRequest {
  organizationId: string;
  /** Narrows the search to one team of the organization (Team audience). */
  teamId?: string;
  query?: string;
  limit?: number;
}

export type SearchSharedContainerMembersResult =
  SearchSharedContainerMembersResponse;

export interface ListSharedContainerRecipientsRequest {
  containerId: string;
  /**
   * Ownership hint. The server locates the container by id alone and, when
   * this is present, requires it to match. Absent for personal containers.
   */
  organizationId?: string;
  cursor?: string;
  limit?: number;
}

export type ListSharedContainerRecipientsResult =
  ListSharedContainerRecipientsResponse;

export interface RevokeSharedContainerRecipientRequest {
  containerId: string;
  /**
   * The grant (or pending email invite) id from the recipients listing. Email
   * recipients expose no user id, so revocation is always by grant id.
   */
  grantId: string;
  /** Ownership hint; see the note on the recipients listing. */
  organizationId?: string;
}

export interface RevokeSharedContainerRecipientResponse {
  revoked: true;
}

export interface ListSharedContainersByMeRequest {
  /** Absent lists the caller's personal containers. */
  organizationId?: string;
  /** Local workspace/project id used to resolve the durable server anchor. */
  projectId: string;
  /** Local worktree or Work Entry id used to resolve the durable server anchor. */
  worktreeId: string;
  cursor?: string;
  limit?: number;
}

export type ListSharedContainersByMeResponse = ListSharedContainersResponse;

/**
 * One local worktree (or Work Entry) that owns a shared container in an
 * organization, produced by the org-wide owner listing (CAN-2551).
 *
 * This single listing serves both the sidebar "shared" badge and the publish
 * status reconciliation in the invite modal, so it carries `revision`: the
 * server is authoritative about whether a container was ever published, while
 * the local publication-state record is only ever a same-machine cache.
 */
export interface SharedContainerOwnedTarget {
  /** Local workspace/project id resolved from the server anchor map. */
  projectId: string;
  /** Local worktree or Work Entry id resolved from the server anchor map. */
  worktreeId: string;
  /** Absent for a personal container. */
  organizationId?: string;
  containerId: string;
  /**
   * Server revision count. `0` means the container exists but has never had a
   * revision committed; `>= 1` means it has been published at least once.
   */
  revision: number;
}

export interface ListSharedContainerOwnedTargetsRequest {
  /** Absent lists the caller's personal containers. */
  organizationId?: string;
  /** Server page size; the handler applies its own bound when omitted. */
  limit?: number;
  /**
   * Upper bound on pages fetched for this organization. Startup hydration fans
   * out over every org, so paging is deliberately bounded rather than
   * exhaustive.
   */
  maxPages?: number;
}

export interface ListSharedContainerOwnedTargetsResponse {
  targets: SharedContainerOwnedTarget[];
  /**
   * True when paging stopped at `maxPages` while the server still had more.
   * Callers must not read an absent target as "not shared" when this is set.
   */
  truncated: boolean;
}

export interface ListSharedContainersWithMeRequest {
  /**
   * Absent lists direct shares: containers shared with the caller by email or
   * from outside their organizations. Those are organization-independent.
   */
  organizationId?: string;
  cursor?: string;
  limit?: number;
}

/**
 * Desktop IPC response for the "shared with me" listing (CAN-2551).
 *
 * Widened past the bare protocol wire type so the main process can report a
 * BENIGN server refusal as data instead of as a rejection. A rejected IPC call
 * cannot carry this: `registerIpcHandler` rejects with a plain `Error` and
 * Electron's structured clone preserves only `message`/`stack`, so a billing
 * refusal would arrive at the renderer indistinguishable from an offline
 * failure and be rendered as "Could not load shared containers."
 *
 * Deliberately NOT added to `@canopy/protocol` — the server response is
 * unchanged and still a 403; the refusal is purely how the desktop main
 * process classifies it for its own renderer. Mirrors the established
 * `SharedContainerEligibilityResponse` typed-refusal pattern.
 */
export interface ListSharedContainersWithMeResponse extends ListSharedContainersResponse {
  /**
   * Set when main classified this organization's empty listing response. A
   * billing refusal is benign and non-retryable. A temporary-unavailability
   * refusal is retryable, and the renderer schedules the next listing attempt.
   */
  refusal?: 'blocked-by-org-billing' | 'temporarily-unavailable';
  /** Server-requested delay for a temporary-unavailability retry, when sent. */
  retryAfterMs?: number;
}

export type SharedContainerAccessBlockReason =
  | 'update-required'
  | 'unsupported-remote-host'
  | 'github-not-connected'
  | 'repository-access-missing'
  | 'commit-unavailable'
  | 'lfs-unsupported'
  | 'symlink-unsupported'
  | 'git-credentials-missing';

/**
 * How the recipient reached a container. `direct` shares are not tied to the
 * recipient's organization membership, so organization reconciliation never
 * purges them. Absent (legacy records) means `organization`.
 */
export type SharedContainerAccess = 'organization' | 'direct';

interface SharedContainerReplicaStateBase {
  containerId: string;
  /** Owning organization; absent for a personal container. */
  organizationId?: string;
  access?: SharedContainerAccess;
  containerType: SharedContainerType;
  updatedAt: string;
}

export type SharedContainerReplicaState =
  | (SharedContainerReplicaStateBase & { status: 'nothing-published' })
  | (SharedContainerReplicaStateBase & {
      status: 'available' | 'pinned';
      revisionId: string;
      revision: number;
      revisionCreatedAt: string;
      withheldFileCount?: number;
      withheldFileReasons?: SharedContainerWithheldFileReason[];
      /** Capability package bound to this exact revision; absent when none. */
      package?: SharedContainerRevisionPackage;
    })
  | (SharedContainerReplicaStateBase & {
      status: 'blocked';
      reason: SharedContainerAccessBlockReason;
      message: string;
      /**
       * Canonical GitHub owner/name for repository-access-missing; absent
       * from legacy entries and other block reasons.
       */
      repository?: string;
    });

/**
 * A replica broadcast that says "these bytes are gone", not "here is new state".
 *
 * The scope is an explicit discriminant rather than an optional `containerId`
 * on a nullable state, because an optional id fails *open*: a call site that
 * forgets it silently degrades to "purge everything", which is exactly the bug
 * that closed an unrelated recipient's open viewer. `purged: 'all'` has to be
 * spelled out.
 *
 * The purge *reason* is deliberately absent from the wire. The renderer's
 * teardown decision is scope plus container id and nothing else; a closed
 * reason union in the preload guard would mean a new main-side reason is
 * silently dropped, leaving decrypted plaintext on screen. The reason is a
 * main-process argument that feeds the session diagnostic instead.
 */
export type SharedContainerReplicaPurge =
  | { purged: 'container'; containerId: string }
  | { purged: 'all' };

/** Everything main can push over `shared-containers:replica-changed`. */
export type SharedContainerReplicaBroadcast =
  | SharedContainerReplicaState
  | SharedContainerReplicaPurge;

/**
 * Why a replica's plaintext was removed.
 *
 * Main-process only - this never crosses IPC (see
 * `SharedContainerReplicaPurge`). It exists so a teardown is attributable in
 * `agent-observability/diagnostics/session-events/` instead of reading as
 * "the viewer closed for no reason".
 */
export type SharedContainerReplicaPurgeReason =
  | 'dismissed'
  | 'access-denied'
  | 'organization-unauthorized'
  | 'account-changed'
  /**
   * The replica index could not account for every byte under the replica
   * root, so the manager self-healed with a whole-store purge. Distinct from
   * `account-changed` on purpose: nobody signed out, and a maintainer triaging
   * this record must not go looking for an account switch that never happened.
   */
  | 'replica-store-unrecoverable';

/**
 * A change to whether main keeps an open recipient viewer live (its realtime
 * subscription plus the fallback pull).
 *
 * Main-process only - this never crosses IPC. It exists so a viewer that stops
 * receiving the publisher's updates is attributable in
 * `agent-observability/diagnostics/session-events/`. Recorded at open/close
 * frequency, never per pull or per realtime signal. Each `released-*` value
 * names what released armed tracking, so a silent stretch can be told apart
 * from the recipient simply leaving.
 */
export type SharedContainerTrackingChange =
  /** An open finished and armed the subscription and the fallback pull. */
  | 'armed'
  /** The viewer session that owns the tracking closed, or a session-less close. */
  | 'released-viewer-closed'
  /** Opening a different share released this one. */
  | 'released-replaced-by-open'
  /** The same share was re-opened under a different access identity. */
  | 'released-identity-changed'
  /** An open finished after the viewer had moved on to another share or to none. */
  | 'released-open-abandoned'
  /** An open or retry of the tracked share failed. */
  | 'released-open-failed'
  /** The replica was purged; see `shared_container_replica_purged`. */
  | 'released-purged'
  /** A close from an earlier viewer session landed late and was ignored. */
  | 'stale-close-ignored'
  /** An open that arrived after the newest viewer session closed was not armed. */
  | 'open-not-armed';

/**
 * Coarse progress of a recipient replica sync (CAN-2551).
 *
 * These ids are internal. Never render them; map through
 * {@link SHARED_CONTAINER_SYNC_PHASE_LABELS} so the copy and the state machine
 * cannot drift, and so no implementation jargon ("sealing", "materializing",
 * "replica", "overlay") reaches the screen.
 */
export const SHARED_CONTAINER_SYNC_PHASES = [
  'checking-access',
  'downloading',
  'checking-out',
  'sealing',
] as const;
export type SharedContainerSyncPhase =
  (typeof SHARED_CONTAINER_SYNC_PHASES)[number];

/** Brand-neutral user-visible copy for each {@link SharedContainerSyncPhase}. */
export const SHARED_CONTAINER_SYNC_PHASE_LABELS: Record<
  SharedContainerSyncPhase,
  string
> = {
  'checking-access': 'Checking your access…',
  downloading: 'Downloading shared files…',
  'checking-out': 'Setting up the code…',
  sealing: 'Finishing up…',
};

export interface SharedContainerSyncPhaseEvent {
  containerId: string;
  phase: SharedContainerSyncPhase;
}

export interface SharedContainerInboxChangedEvent {
  /**
   * `local` is this device's own remove or restore: main emits it at once,
   * outside the realtime debounce, so every section re-lists what changed.
   */
  reason: 'realtime' | 'poll' | 'focus' | 'local';
}

export interface SharedContainerRecipientRequest {
  containerId: string;
  /** Optional bounded analytics hint from the listing; never authorization. */
  containerType?: SharedContainerType;
  /** Ownership hint; absent for a personal container shared directly. */
  organizationId?: string;
  access?: SharedContainerAccess;
}

/**
 * Per-device record that the recipient explicitly accepted a shared container.
 *
 * Acceptance is the gate on materialization: nothing is cloned, fetched, or
 * written for a container the recipient has not accepted. It is device-local on
 * purpose, because what it authorizes is use of *this* machine's disk and
 * network, which a decision made on another machine cannot speak for.
 */
export interface SharedContainerAcceptanceRecord {
  /** Absent for a personal container shared directly. */
  organizationId?: string;
  /** Absent on records written before external sharing; read as `organization`. */
  access?: SharedContainerAccess;
  acceptedAt: string;
  runAllowedAt?: string;
  runAllowedPublisherUserId?: string;
}

/** Persisted file backing recipient shared-container acceptance. */
export interface SharedContainerAcceptanceFile {
  version: 1;
  accepted: Record<string, SharedContainerAcceptanceRecord>;
}

/**
 * The identity a share was accepted under. It is written once per accept and
 * decides which workspace context lists the accepted share, independent of how
 * a later listing round classifies it.
 */
export type SharedContainerAcceptedIdentity = Pick<
  SharedContainerAcceptanceRecord,
  'organizationId' | 'access'
> & {
  /**
   * When this device accepted the share. Optional: identities the renderer
   * persisted before it was carried have none, and sort last.
   */
  acceptedAt?: string;
};

export interface ListAcceptedSharedContainersResponse {
  containerIds: string[];
  /**
   * Recorded identity per accepted container, keyed like `containerIds`.
   * Optional so a responder that predates it still satisfies the contract.
   */
  records?: Record<string, SharedContainerAcceptedIdentity>;
}

export interface AcceptSharedContainerResponse {
  accepted: true;
  /**
   * The identity the acceptance record holds after this accept: the one just
   * written, or the one a repeat accept kept. Optional so a responder that
   * predates it still satisfies the contract.
   */
  record?: SharedContainerAcceptedIdentity;
}

export interface SharedContainerRunConsentRequest {
  containerId: string;
  publisherUserId: string;
}

export interface SharedContainerRunStatusRequest {
  containerId: string;
  revisionId: string;
}

export interface SharedContainerRunEnvironmentRequest {
  containerId: string;
  /** New plaintext values, or stored-secret values to keep. */
  values: UserEnvironmentEntryView[];
}

export interface SharedContainerRunRefreshRequest extends SharedContainerRunStatusRequest {
  stopRunning?: boolean;
}

export interface SharedContainerRunStatus {
  allowed: boolean;
  allowedAt?: string;
  publisherUserId?: string;
  run?: SharedContainerRevisionRunConfig;
  /** Every non-empty value is a stored-secret value. */
  values: UserEnvironmentEntryView[];
  unsetRequiredEnv: string[];
  runCopySizeBytes: string;
  /** A committed copy exists for an older revision, or recovery is pending. */
  runCopyNeedsRefresh: boolean;
  /** Live PTYs or published-command runs currently own the run copy. */
  hasRunningProcesses: boolean;
}

export interface GetSharedContainerReplicaStateRequest {
  containerId: string;
}

/**
 * Opens (or retries) a recipient's viewer of a shared container.
 *
 * `viewerSessionId` identifies the renderer viewer mount this open belongs to.
 * Main keeps the newest session per container so that a close from an earlier
 * visit, which can land late, cannot release the live tracking of the visit
 * now on screen. A retry reuses the session of the viewer it retries. Absent
 * on legacy callers, whose closes stay unconditional.
 */
export interface OpenSharedContainerRequest extends SharedContainerRecipientRequest {
  viewerSessionId?: string;
}

/**
 * Closes a recipient's viewer. With a `viewerSessionId`, the close only
 * releases tracking and stops processes when that session is still the newest
 * one main has seen for the container; without one it is unconditional.
 */
export interface CloseSharedContainerRequest {
  containerId: string;
  viewerSessionId?: string;
}

export interface DismissSharedContainerResponse {
  dismissed: true;
}

export interface ListDismissedSharedContainersRequest {
  /** Absent lists removed direct shares, like the shared-with-me listing. */
  organizationId?: string;
  cursor?: string;
  limit?: number;
}

/**
 * Shares this recipient removed and may still restore. `unsupported` is data,
 * not a rejection: the connected server predates recoverable removal, so
 * the renderer keeps the irreversible-remove copy and offers no restore.
 */
export type ListDismissedSharedContainersResult =
  | ListDismissedSharedContainersResponse
  | { unsupported: true };

/**
 * Notices that a share ended because its owner left the organization.
 * `unsupported` means notices are unavailable on the server or to the current
 * credential. The renderer clears its cache on that result.
 */
export type ListSharedContainerOwnerDeparturesResult =
  | ListSharedContainerOwnerDeparturesResponse
  | { unsupported: true };

export interface DismissSharedContainerOwnerDepartureRequest {
  noticeId: string;
}

/** A notice the server no longer has is already dismissed. Unavailable access clears the cache. */
export type DismissSharedContainerOwnerDepartureResult =
  | { dismissed: true }
  | { unsupported: true };

/**
 * `not-restorable` covers every server 404: the owner revoked the removed
 * share, or it is no longer shared with this account. The server does not say
 * which, and neither does this.
 */
export type RestoreSharedContainerResult =
  | { restored: true; container: SharedContainerSummary }
  | { restored: false; reason: 'not-restorable' | 'unsupported' };

export interface SharedContainerRevisionRequest {
  containerId: string;
  revisionId: string;
}

export interface SharedContainerContentListRequest extends SharedContainerRevisionRequest {
  cursor?: string;
  limit?: number;
}

export interface SharedContainerContentPage<T> {
  items: T[];
  nextCursor: string | null;
  truncated: boolean;
}

export interface SharedContainerChatSummary {
  chatId: string;
  title: string;
  createdAt: string;
  description?: string;
}

export interface SharedContainerPlanSummary {
  planId: string;
  title: string;
  updatedAt: string;
  reviewStatus: string;
}

export interface SharedContainerWorkspaceItemSummary {
  itemId: string;
  title: string;
  createdAt?: string;
  updatedAt?: string;
}

export interface SharedContainerAttachmentSummary {
  attachmentId: string;
  displayName: string;
}

/**
 * Which half of the share a changed file belongs to (CAN-2551).
 *
 * `uncommitted` files are published as encrypted artifacts and materialized
 * into the replica overlay. `committed` files are metadata only; their content
 * resolves from the recipient's own checkout between the manifest's
 * `mergeBaseSha` and `baseCommitSha`.
 */
export const SHARED_CONTAINER_FILE_SOURCES = [
  'uncommitted',
  'committed',
] as const;
export type SharedContainerFileSource =
  (typeof SHARED_CONTAINER_FILE_SOURCES)[number];

export interface SharedContainerRepositoryTreeEntry {
  repoId: string;
  path: string;
  kind: 'file' | 'directory';
  sizeBytes?: string;
  /** Present on files only; directories are derived from their descendants. */
  status?: SharedContainerFileStatus;
  /** Present on files only. */
  source?: SharedContainerFileSource;
  /** Publisher-computed counts. Only committed files carry real numbers. */
  insertions?: number;
  deletions?: number;
}

export interface SharedContainerRepositorySummary {
  repoId: string;
  repoName: string;
  /**
   * Commit the publisher's working-tree changes were taken against (CAN-2551).
   *
   * Display metadata for the recipient, so a share with nothing in it can say
   * *which* point in history it is empty relative to instead of reading as a
   * bug. Absent for Cowork shares, which have no repository history.
   */
  baseCommitSha?: string;
  /**
   * Branch the publisher's commits were compared against. Optional: a revision
   * published before CAN-2551, or one whose base branch could not be resolved,
   * simply omits it.
   */
  baseBranch?: string;
}

/** Authenticated display metadata read from the materialized revision layout. */
export interface SharedContainerRevisionMetadata {
  title: string;
}

export interface ReadSharedContainerForkProvenanceRequest {
  projectId: string;
  worktreeId: string;
}

export interface ReadSharedContainerChatRequest extends SharedContainerRevisionRequest {
  chatId: string;
}

export interface ReadSharedContainerPlanRequest extends SharedContainerRevisionRequest {
  planId: string;
}

export interface ReadSharedContainerWorkspaceItemRequest extends SharedContainerRevisionRequest {
  itemId: string;
}

export interface ReadSharedContainerAttachmentRequest extends SharedContainerRevisionRequest {
  attachmentId: string;
}

export interface ListSharedContainerRepositoryTreeRequest extends SharedContainerContentListRequest {
  repoId: string;
}

export interface ReadSharedContainerOverlayDiffRequest extends SharedContainerRevisionRequest {
  repoId: string;
  path: string;
  /**
   * Defaults to `'uncommitted'` so a renderer that predates CAN-2551 keeps its
   * current artifact-backed behavior.
   */
  source?: SharedContainerFileSource;
}

export interface SharedContainerAttachmentContent {
  displayName: string;
  data: Uint8Array;
  sizeBytes: string;
  truncated: boolean;
}

export interface SharedContainerOverlayDiff {
  oldValue: string;
  newValue: string;
  truncated: boolean;
  binary: boolean;
  imagePreview?: FileDiffImagePreview;
}

export interface SharedContainersApi {
  checkEligibility(
    request: SharedContainerEligibilityRequest,
  ): Promise<SharedContainerEligibilityResponse>;
  prepareGithub(
    request: SharedContainerPrepareGithubRequest,
  ): Promise<SharedContainerPrepareGithubResponse>;
  preview(
    request: SharedContainerPreviewRequest,
  ): Promise<SharedContainerSharePreview>;
  saveFileScope(
    request: SaveSharedContainerFileScopeRequest,
  ): Promise<SaveSharedContainerFileScopeResponse>;
  invite(
    request: InviteSharedContainerRequest,
  ): Promise<InviteSharedContainerResponse>;
  getLink(
    request: SharedContainerLinkOwnerRequest,
  ): Promise<SharedContainerLink | null>;
  setLink(
    request: SetSharedContainerLinkIpcRequest,
  ): Promise<SetSharedContainerLinkIpcResponse>;
  resetLink(
    request: SharedContainerLinkOwnerRequest,
  ): Promise<SharedContainerLink>;
  resolveLink(
    request: SharedContainerLinkTokenRequest,
  ): Promise<SharedContainerLinkLanding>;
  claimLink(
    request: SharedContainerLinkTokenRequest,
  ): Promise<SharedContainerLinkClaimResult>;
  searchMembers(
    request: SearchSharedContainerMembersRequest,
  ): Promise<SearchSharedContainerMembersResult>;
  listRecipients(
    request: ListSharedContainerRecipientsRequest,
  ): Promise<ListSharedContainerRecipientsResult>;
  revokeRecipient(
    request: RevokeSharedContainerRecipientRequest,
  ): Promise<RevokeSharedContainerRecipientResponse>;
  listSharedByMe(
    request: ListSharedContainersByMeRequest,
  ): Promise<ListSharedContainersByMeResponse>;
  /**
   * Org-wide owner listing (CAN-2551): every container this user owns in the
   * organization, reverse-mapped to local `(projectId, worktreeId)` pairs.
   * Unlike {@link listSharedByMe} this is not scoped to one worktree, and it
   * fails soft - a listing error surfaces as no targets, never as a blocked
   * sidebar render.
   */
  listOwnedTargets(
    request: ListSharedContainerOwnedTargetsRequest,
  ): Promise<ListSharedContainerOwnedTargetsResponse>;
  /**
   * Recipient bridge (CAN-2549). Content is fetched on {@link open} only, never
   * on invitation; {@link close} releases the realtime subscription.
   */
  listSharedWithMe(
    request: ListSharedContainersWithMeRequest,
  ): Promise<ListSharedContainersWithMeResponse>;
  open(
    request: OpenSharedContainerRequest,
  ): Promise<SharedContainerReplicaState>;
  getReplicaState(
    request: GetSharedContainerReplicaStateRequest,
  ): Promise<SharedContainerReplicaState | null>;
  /** Container ids this device has accepted, and may therefore materialize. */
  listAccepted(): Promise<ListAcceptedSharedContainersResponse>;
  /**
   * Records recipient consent to materialize this container on this device.
   * `open` fails closed until this has been called.
   */
  accept(
    request: SharedContainerRecipientRequest,
  ): Promise<AcceptSharedContainerResponse>;
  /** Removes the share from this recipient's view without revoking the grant. */
  dismiss(
    request: SharedContainerRecipientRequest,
  ): Promise<DismissSharedContainerResponse>;
  /** Shares this recipient removed and may still restore (CAN-4052). */
  listDismissed(
    request: ListDismissedSharedContainersRequest,
  ): Promise<ListDismissedSharedContainersResult>;
  /** Notices that shares ended because their owners left (CAN-5120). */
  listOwnerDepartures(): Promise<ListSharedContainerOwnerDeparturesResult>;
  dismissOwnerDeparture(
    request: DismissSharedContainerOwnerDepartureRequest,
  ): Promise<DismissSharedContainerOwnerDepartureResult>;
  /** Returns a removed share to the inbox as a pending invitation. */
  restore(
    request: SharedContainerRecipientRequest,
  ): Promise<RestoreSharedContainerResult>;
  /** Re-runs the access gate for a blocked container. */
  retry(
    request: OpenSharedContainerRequest,
  ): Promise<SharedContainerReplicaState>;
  close(request: CloseSharedContainerRequest): Promise<void>;
  /**
   * Recipient run affordance (CAN-2831). Reports whether this device has
   * granted the share permission to run code, what the publisher published,
   * and which declared environment names are still unset.
   *
   * Fails closed in main: the request rejects when the run flag is off, the
   * platform is not macOS, or the device has not accepted the share. Renderers
   * therefore treat a rejection as "no run affordance", never as an error the
   * recipient has to act on.
   */
  runStatus(
    request: SharedContainerRunStatusRequest,
  ): Promise<SharedContainerRunStatus>;
  /**
   * Records this device's consent for the share to execute publisher-authored
   * code. One grant covers both the published commands and the terminal, and
   * it lasts until {@link revokeRun} or a dismiss.
   */
  allowRun(request: SharedContainerRunConsentRequest): Promise<void>;
  /**
   * Withdraws run consent. Main stops live terminals and script runs for the
   * container before clearing the grant, so revocation cannot leave a process
   * behind.
   */
  revokeRun(request: GetSharedContainerReplicaStateRequest): Promise<void>;
  /**
   * Persists the recipient's own values for the publisher-declared names.
   * Encrypted at rest and scoped to this container; main rejects any name the
   * revision did not declare. Resolves with the stored entries, each
   * non-empty value as a stored-secret value, which callers adopt rather than
   * keeping their own draft.
   */
  saveRunEnvironment(
    request: SharedContainerRunEnvironmentRequest,
  ): Promise<UserEnvironmentEntryView[]>;
  /**
   * Rebuilds the writable run copy from the sealed replica. Rejects while
   * terminals or script runs are live unless `stopRunning` is set, because the
   * publisher wins on refresh and overwriting under a running dev server is
   * incoherent.
   */
  refreshRunCopy(request: SharedContainerRunRefreshRequest): Promise<void>;
  /** Copies one accepted revision into an independent local container. */
  fork(request: SharedContainerForkRequest): Promise<SharedContainerForkResult>;
  readForkProvenance(
    request: ReadSharedContainerForkProvenanceRequest,
  ): Promise<SharedContainerForkProvenance | null>;
  readRevisionMetadata(
    request: SharedContainerRevisionRequest,
  ): Promise<SharedContainerRevisionMetadata>;
  listChats(
    request: SharedContainerContentListRequest,
  ): Promise<SharedContainerContentPage<SharedContainerChatSummary>>;
  readChat(
    request: ReadSharedContainerChatRequest,
  ): Promise<SharedContainerPublishedChat>;
  listPlans(
    request: SharedContainerContentListRequest,
  ): Promise<SharedContainerContentPage<SharedContainerPlanSummary>>;
  readPlan(
    request: ReadSharedContainerPlanRequest,
  ): Promise<SharedContainerPublishedPlan>;
  listNotes(
    request: SharedContainerContentListRequest,
  ): Promise<SharedContainerContentPage<SharedContainerWorkspaceItemSummary>>;
  readNote(request: ReadSharedContainerWorkspaceItemRequest): Promise<string>;
  listPrompts(
    request: SharedContainerContentListRequest,
  ): Promise<SharedContainerContentPage<SharedContainerWorkspaceItemSummary>>;
  readPrompt(request: ReadSharedContainerWorkspaceItemRequest): Promise<string>;
  listAttachments(
    request: SharedContainerContentListRequest,
  ): Promise<SharedContainerContentPage<SharedContainerAttachmentSummary>>;
  readAttachment(
    request: ReadSharedContainerAttachmentRequest,
  ): Promise<SharedContainerAttachmentContent>;
  listRepositories(
    request: SharedContainerRevisionRequest,
  ): Promise<SharedContainerRepositorySummary[]>;
  listRepositoryTree(
    request: ListSharedContainerRepositoryTreeRequest,
  ): Promise<SharedContainerContentPage<SharedContainerRepositoryTreeEntry>>;
  readOverlayDiff(
    request: ReadSharedContainerOverlayDiffRequest,
  ): Promise<SharedContainerOverlayDiff>;
  onReplicaChanged(
    callback: (event: SharedContainerReplicaBroadcast) => void,
  ): () => void;
  /** Coarse open/sync progress, so a multi-second checkout does not read as a hang. */
  onSyncPhase(
    callback: (event: SharedContainerSyncPhaseEvent) => void,
  ): () => void;
  onPublicationChanged(
    callback: (state: SharedContainerPublicationState) => void,
  ): () => void;
  onInboxChanged?(
    callback: (event: SharedContainerInboxChangedEvent) => void,
  ): () => void;
}

