export interface FilePreviewResponse {
  kind: 'image' | 'text' | 'markdown' | 'html' | 'unsupported';
  content: string;
  filename: string;
  sizeBytes: number;
  truncated: boolean;
  /**
   * `fs.stat().mtimeMs` of the file at read time. Round-tripped by the
   * renderer back to the backend on save (`SaveFileContentRequest.expectedModifiedAtMs`)
   * so the backend can detect concurrent on-disk modifications and reject
   * the write rather than silently overwriting the newer state.
   */
  modifiedAtMs: number;
}

export interface FileDocumentBytesRequest {
  absolutePath: string;
  /** Required: reads are realpath-contained to the worktree roots. */
  workspaceTarget: ShowFilesWorkspaceTarget;
}

export type FileDocumentBytesResponse =
  | {
      status: 'ready';
      bytes: Uint8Array;
      filename: string;
      sizeBytes: number;
      modifiedAtMs: number;
    }
  | { status: 'too-large'; maxBytes: number; sizeBytes: number }
  | { status: 'missing' };

/**
 * Request shape for `IPC_CHANNELS.fileReadContent`. Mirrors
 * `FilePreviewRequest` but the backing handler reads with a larger size cap
 * (`MAX_TEXT_BYTES_FULL = 5 * 1024 * 1024`) so file-tab consumers can render
 * full file contents rather than a small preview slice.
 */
export interface FileContentRequest {
  absolutePath: string;
  /**
   * Restricts provider-supplied generated-image paths to the canonical Codex
   * generated-images directory before the main process opens the file.
   */
  allowedRoot?: 'codex-generated-images';
  /**
   * When supplied, the main process resolves the candidate and workspace
   * roots through realpath and rejects reads outside those canonical roots.
   * Agent-driven ShowFiles reads must always supply this target.
   */
  workspaceTarget?: ShowFilesWorkspaceTarget;
  /**
   * The root identity of a scoped read (CAN-4099). With `workspaceTarget`,
   * main reads the file as `worker.filesystem.file.read` addresses it and
   * answers with `canonical`; `absolutePath` stays for hosts that predate it.
   */
  file?: FileContentReadIdentity;
}

export interface FileContentReadIdentity {
  fileRootId: string;
  /** Root-relative, `/`-separated, without `.` or `..` segments. */
  relativePath: string;
}

/**
 * The `worker.filesystem.file.read` result behind a scoped response, without
 * its content (CAN-4099). Present only when the request named `file`.
 */
export interface FileContentCanonicalRead {
  fileRootId: string;
  relativePath: string;
  /** The resolved file's name. */
  name: string;
  contentKind: 'text' | 'markdown' | 'html' | 'image' | 'unsupported';
  mediaType?: string;
  sizeBytes: number;
  returnedBytes: number;
  truncated: boolean;
  /** RFC 3339, millisecond precision. */
  modifiedAt: string;
  /** Opaque `size:round(mtimeMs)` save-conflict token. */
  version: string;
}

/**
 * Response shape for `IPC_CHANNELS.fileReadContent`.
 *
 * The `kind` union mirrors `FilePreviewResponse` for readable files, with an
 * additional `'missing'` kind for paths that no longer exist. CSV is **not** a
 * separate kind — it stays classified as `'text'`, and the renderer detects it
 * via `filename.toLowerCase().endsWith('.csv')`.
 *
 * Size cap: `MAX_TEXT_BYTES_FULL = 5 * 1024 * 1024` (5 MB). Image reads share
 * the same 5 MB cap as the existing preview handler. A null-byte sniff inside
 * the read slice promotes a candidate text file to `'unsupported'` even when
 * its extension is not on the binary list.
 */
export interface FileContentResponse {
  /**
   * Classification of the file's contents.
   *
   * - `'image'`      — `content` is a data URI (e.g. `data:image/png;base64,...`)
   * - `'text'`       — `content` is the raw UTF-8 file body
   * - `'markdown'`   — `content` is the raw UTF-8 file body
   * - `'html'`       — `content` is the raw UTF-8 file body; the renderer can
   *   sandbox-render it via an `<iframe srcDoc>` preview or open the file in
   *   the user's default browser.
   * - `'unsupported'` — `content` is the empty string; the renderer falls back
   *   to an "Open in Finder" affordance using `filename` + `sizeBytes`.
   * - `'missing'`     — the file does not exist on disk (read failed with
   *   `ENOENT`). `content` is the empty string and the renderer shows a clean
   *   "File does not exist" state instead of surfacing the raw IPC error.
   */
  kind: 'image' | 'text' | 'markdown' | 'html' | 'unsupported' | 'missing';
  /**
   * For `'image'`: data URI (e.g. `data:image/png;base64,...`).
   * For `'text'` / `'markdown'` / `'html'`: raw file contents (UTF-8).
   * For `'unsupported'` / `'missing'`: empty string.
   */
  content: string;
  /**
   * Basename of the file. Used by the renderer to detect e.g. CSV via
   * extension and to display context next to fallback affordances.
   */
  filename: string;
  /** File size in bytes from `fs.stat`. */
  sizeBytes: number;
  /** True if the response was clipped to `MAX_TEXT_BYTES_FULL`. */
  truncated: boolean;
  /**
   * `fs.stat().mtimeMs` of the file at read time. Round-tripped by the
   * renderer back to the backend on save (`SaveFileContentRequest.expectedModifiedAtMs`)
   * so the backend can detect concurrent on-disk modifications and reject
   * the write rather than silently overwriting the newer state.
   */
  modifiedAtMs: number;
  /** The canonical read, when the request named `file` (CAN-4099). */
  canonical?: FileContentCanonicalRead;
}

/**
 * Request shape for `IPC_CHANNELS.fileSaveContent`. The renderer sends the new
 * UTF-8 file body together with the `modifiedAtMs` it loaded the file with so
 * the backend can detect concurrent on-disk modifications and reject the save
 * rather than overwriting newer changes.
 *
 * Negotiated image saves instead supply `createOnly: true` and the advertised
 * format's encoding, without an edit version. PNG/base64 and SVG/UTF-8 are
 * bounded to 5 MiB, create a missing file exclusively, and return metadata.
 * Missing imageSaveSupport means this extension is unavailable.
 *
 * The default text editor path rejects the save in any of these cases:
 *
 * - `validateId` fails for `projectId` or `worktreeId`.
 * - `absolutePath` is relative or otherwise invalid.
 * - The file extension classifies as `'image'` or `'unsupported'`.
 * - UTF-8 byte length of `content` exceeds `MAX_EDIT_TEXT_BYTES` (5 MB).
 * - `content` contains a `\0` null byte.
 * - The real path of the file lies outside allowed worktree roots.
 * - The target is a standalone chat project.
 * - `realpath` of the file path returns `ENOENT` (file no longer exists; this
 *   surface only edits files that already exist).
 * - `expectedModifiedAtMs` is supplied and the current `stat().mtimeMs`
 *   differs by more than 1 ms (`Math.abs(currentMtimeMs - expectedModifiedAtMs) > 1`).
 */
export interface SaveFileContentRequest extends FileSaveOptions {
  projectId: string;
  worktreeId: string;
  absolutePath: string;
  content: string;
  /**
   * `modifiedAtMs` from the confirmed `readFileContent` / `readFilePreview`.
   * `file:save-content` rejects with `FileSaveConflictError` when the current
   * `stat().mtimeMs` differs by more than 1 ms. Electron invoke wraps that
   * error's name; the client adapter must restore the shared error identity.
   * Recovery writes must supply the freshly confirmed version, including
   * an explicit replacement of a newer version. For text edits, omission
   * retains the legacy unconditional-save behavior and must never bypass a
   * conflict. Negotiated create-only image saves must omit this edit version.
   */
  expectedModifiedAtMs?: number;
}

/**
 * Response shape for `IPC_CHANNELS.fileSaveContent`. Populated from the
 * post-write `fs.stat` so the renderer can use the returned `modifiedAtMs`
 * as the `expectedModifiedAtMs` for the next save without re-reading the
 * file.
 */
export interface SaveFileContentResponse {
  /** Basename of the saved file. */
  filename: string;
  /** Post-write `fs.stat().size`. */
  sizeBytes: number;
  /** Post-write `fs.stat().mtimeMs`. */
  modifiedAtMs: number;
}

