/**
 * Payload describing a hook chat that has been queued because another chat is
 * already active in the target worktree. The renderer uses this to render a
 * transient placeholder tab while the queued hook waits its turn.
 *
 * - `queueId` uniquely identifies the queued entry so the renderer can later
 *   cancel it via `chat:cancel-queued-hook-chat`.
 * - `text` is the queued prompt preview (typically the first line of the
 *   hook prompt) for display in the placeholder.
 * - `reason` is the human-readable explanation for why the hook is queued.
 *   For the wire protocol this is exactly:
 *   "Waiting for active chat sessions to finish."
 *   The renderer must render this verbatim.
 * - `hookInfo` identifies the hook that fired and when, so the placeholder can
 *   show the same "Chat initiated by … hook" banner the started chat carries.
 *   The started chat's `hook_info` block reuses this timestamp.
 */
export interface HookChatQueuedMessage {
  queueId: string;
  text: string;
  reason: string;
  hookInfo?: { triggerName: string; timestamp: number };
}

export interface HookChatQueueRemovedEvent {
  projectId: string;
  worktreeId: string;
  chatId: string;
  queueId: string;
}

export interface HookChatTabStartedEvent {
  projectId: string;
  worktreeId: string;
  chatId: string;
  tab: PersistedChatTab;
  activateTab: boolean;
  /**
   * When present, the event represents a transient queued placeholder tab —
   * the hook chat has not yet started and is waiting for active chat sessions
   * in its target worktree to finish. The renderer should not persist the tab
   * in this case.
   *
   * When absent, the event represents a real start: either an immediate
   * launch when no concurrency conflict exists, or a previously-queued tab
   * transitioning from queued to running.
   */
  queuedMessage?: HookChatQueuedMessage;
}

