/**
 * Cmd+K unified fuzzy search — transport contract (IPC).
 *
 * Only tiers 1 (chat titles) and 2 (transcript content) cross the process
 * boundary; the shapes below are the single source of truth shared by the
 * renderer palette and the main-process chat-search service.
 */

/**
 * Origin of a catalog/search doc. `live` is an active chat; the `*-archive`
 * variants are legacy archived transcripts (worktree chats vs. cowork/home
 * chats); `archived-container` is a transcript retained with its deleted
 * worktree/work entry; `plan` is a tracked plan document (title + markdown
 * content).
 */
export type ChatSearchSource =
  | 'live'
  | 'worktree-archive'
  | 'cowork-archive'
  | 'archived-container'
  | 'plan';

/** What a search document represents, independently of where it is stored. */
export type ChatSearchDocumentKind =
  | 'chat'
  | 'chat-child'
  | 'plan'
  | 'archived-container';

/** Locates a retained delegation transcript relative to its parent chat. */
export interface ChatSearchChildLocator {
  delegationId: string;
  runGeneration: number;
}

/**
 * A single document in the search catalog. Mirrors the backend
 * `chat_docs` columns **minus `body`**, keeping the palette-open payload lean.
 * The renderer joins workspace/branch display names from `projectsStore`
 * client-side — the catalog carries only ids, never resolved names.
 */
export interface ChatSearchCatalogEntry {
  /** Parent chat identity, or an escaped child tuple for `chat-child` docs. */
  docId: string;
  /** Workspace id | `APP_ADVISOR_PROJECT_ID`. */
  projectId: string;
  /** Worktree id | `'home'` (cowork) | `'global'` (advisor). */
  worktreeId: string;
  chatId: string;
  source: ChatSearchSource;
  /**
   * Defaults to `plan` for the legacy `plan` source and `chat` otherwise.
   * New index rows always populate this field; optionality keeps older
   * renderer fixtures and persisted derived-index rows forward compatible.
   */
  documentKind?: ChatSearchDocumentKind;
  /** Present only when the best content match is a retained child transcript. */
  childLocator?: ChatSearchChildLocator;
  title: string;
  /** Chat or archived-container summary description. */
  description?: string | null;
  providerType?: string | null;
  /** Epoch ms — last message ts (fallback createdAt/archivedAt). */
  updatedAt: number;
  /** null for live docs. */
  archivedAt?: number | null;
  /**
   * Retention deadline (epoch ms) for docs owned by a retained container.
   * `null` for live docs and for "Archived" (locked) containers, which never
   * expire; set for "Deleted" containers the sweep will remove.
   */
  expiresAt?: number | null;
  messageCount: number;
  /** Review status — set only for `plan` docs. */
  reviewStatus?: TrackedPlanReviewStatus | null;
}

/**
 * Catalog response — the most-recent ~2000 entries by `updatedAt`. Fetched
 * once per palette open.
 */
export interface ChatSearchCatalogResponse {
  entries: ChatSearchCatalogEntry[];
}

/**
 * Renderer-derived Personal checkout ids linked into the selected
 * organization's sidebar projection. Navigation context is not an
 * authorization boundary; main still combines this hint with its own current
 * context and persisted owner lookup before returning search rows.
 */
export interface ChatSearchScopeHint {
  linkedPersonalWorkspaceIds?: string[];
}

/**
 * Catalog request. With `chatIds` the catalog returns only those chats' rows
 * (live and archived copies) however old they are, instead of the newest page;
 * an empty list returns nothing. Visibility and scoping are unchanged.
 */
export interface ChatSearchCatalogRequest extends ChatSearchScopeHint {
  chatIds?: readonly string[];
}

/**
 * Query request — accepts a **raw user string**. Sanitizing the string into
 * safe FTS5 tokens (quoting, prefix-star) is a backend responsibility;
 * transport only guarantees an arbitrary user string is accepted without error.
 */
export interface ChatSearchQueryRequest extends ChatSearchScopeHint {
  query: string;
  /** Default ~20. */
  limit?: number;
}

/**
 * A single highlight range into a result `snippet`. Plain integer offsets
 * (MatchSegment-compatible) so the renderer can reuse its highlight component
 * without any knowledge of FTS internals.
 */
export interface ChatSearchMatchRange {
  start: number;
  end: number;
}

/**
 * A single FTS match — catalog-entry fields + `snippet` + `matchRanges`. The
 * backend produces `matchRanges` by parsing FTS5 `snippet()` sentinel
 * delimiters main-side; the wire format is plain integer ranges into `snippet`.
 */
export interface ChatSearchResult extends ChatSearchCatalogEntry {
  snippet: string;
  /** Ranges into `snippet`. */
  matchRanges: ChatSearchMatchRange[];
}

export interface ChatSearchQueryResponse {
  results: ChatSearchResult[];
}

/**
 * Renderer-facing bridge for the Cmd+K unified fuzzy chat search. Two
 * round-trips cross the process boundary, plus a payload-less refresh event:
 * - {@link catalog} — fetched once on palette open (tier 1).
 * - {@link query} — debounced per settled query (tier 2).
 * - {@link onUpdated} — subscribes to the `chatSearchUpdated` broadcast.
 */
export interface ChatSearchApi {
  catalog(
    request?: ChatSearchCatalogRequest,
  ): Promise<ChatSearchCatalogResponse>;
  query(req: ChatSearchQueryRequest): Promise<ChatSearchQueryResponse>;
  /**
   * Subscribe to the payload-less, main→renderer `chatSearchUpdated` broadcast
   * ("the index changed — re-read"). The backend emits it when the initial
   * lazy scan completes and after each incremental-reindex flush (coalesced).
   * On receipt the renderer re-fetches {@link catalog} and re-issues any active
   * tier-2 {@link query}. Returns an unsubscribe function; the palette
   * subscribes on mount and unsubscribes on close.
   */
  onUpdated(cb: () => void): () => void;
}

export interface DependencyVersions {
  claudeCli: string;
  claudeSdk: string;
  codexCli: string;
  ghCli: string;
  octokit: string;
  rtkCli: string;
}

export interface UpdateApi {
  checkForUpdates(): Promise<void>;
  checkForVersion?(request: TargetUpdateRequest): Promise<void>;
  listVersions?(
    request?: TargetUpdateVersionListRequest,
  ): Promise<TargetUpdateVersionListResponse>;
  downloadUpdate(): Promise<void>;
  installUpdate(): Promise<void>;
  scheduleUpdate(): Promise<void>;
  cancelScheduledUpdate(): Promise<void>;
  reportBusyState(busy: boolean): Promise<void>;
  getAppVersion(): Promise<string>;
  getDependencyVersions(): Promise<DependencyVersions>;
  getState(): Promise<UpdateState>;
  onUpdateEvent(cb: (event: UpdateEvent) => void): () => void;
}

export interface CliApi {
  getStatus(): Promise<CliPathStatus>;
  installToPath(): Promise<CliInstallResult>;
  uninstallFromPath(): Promise<CliInstallResult>;
}

