  updateClaudeMods: (
    update: ClaudeModsUpdate,
  ) => Promise<ClaudeModsUpdateResult>;
  /**
   * Persists ONE approval surface default, merged inside the preferences write
   * queue. Settings must use this rather than `savePreferences` with a whole
   * `approvalDefaults` object: that path writes a snapshot taken at mount, so
   * it clobbers a concurrent in-chat write-back and — when `loadPreferences()`
   * failed and the snapshot came from a synthetic fallback — silently escalates
   * the surfaces the user never touched (CAN-3055).
   */
  setApprovalDefaultPreference: (
    request: SetApprovalDefaultPreferenceRequest,
  ) => Promise<PreferencesData>;
  createPrimaryDataDir: () => Promise<ResolvedCanopyDataDir>;
