export type SlowActionKind =
  | 'ipc'
  | 'chat'
  | 'pipeline'
  | 'terminal'
  | 'resource-monitor'
  | 'portal'
  | 'unknown';

export interface SlowActionRecord {
  id: string;
  kind: SlowActionKind;
  label: string;
  startedAt: string;
  startedAtMs: number;
  thresholdMs: number;
  context?: {
    channel?: string;
    projectId?: string;
    worktreeId?: string;
    chatId?: string;
    pipelineExecutionId?: string;
    terminalId?: string;
  };
}

export interface SlowActionSnapshot {
  records: SlowActionRecord[];
}

export type SlowActionEvent =
  | {
      type: 'added';
      record: SlowActionRecord;
    }
  | {
      type: 'resolved';
      id: string;
    }
  | {
      type: 'evicted';
      id: string;
    }
  | {
      type: 'cleared';
    };

export interface SlowActionApi {
  loadSnapshot: () => Promise<SlowActionSnapshot>;
  clear: () => Promise<void>;
  onEvent: (listener: (event: SlowActionEvent) => void) => () => void;
}

/**
 * Identifies a single voice capture session. Generated by the renderer and
 * echoed on every event so races between sessions can be disambiguated.
 */
export interface VoiceStartRequest {
  sessionId: string;
}

export interface VoiceStartResponse {
  sessionId: string;
}

export interface VoicePushAudioRequest {
  sessionId: string;
  /** 16 kHz mono signed 16-bit little-endian PCM, chunked by the renderer. */
  pcm: ArrayBuffer;
}

export interface VoiceStopRequest {
  sessionId: string;
}

export interface VoiceCancelRequest {
  sessionId: string;
}

export interface VoiceOpenSettingsRequest {
  /**
   * macOS `x-apple.systempreferences:` deep-link. Only URLs with this scheme
   * are accepted by the main-process handler.
   */
  url: string;
}

export interface VoiceIsSupportedResponse {
  supported: boolean;
  reason?: string;
}

/**
 * macOS microphone access status. Mirrors Electron's
 * `systemPreferences.getMediaAccessStatus('microphone')` return values, with
 * an added `'unavailable'` for platforms where the query is not supported
 * (e.g. Linux) or when the query itself fails.
 */
export type VoiceMicrophoneAccess =
  | 'granted'
  | 'denied'
  | 'not-determined'
  | 'restricted'
  | 'unknown'
  | 'unavailable';

export type VoiceSpeechRecognitionAccess =
  | 'authorized'
  | 'denied'
  | 'not-determined'
  | 'restricted'
  | 'unknown'
  | 'unavailable';

export interface VoiceSystemAccessResponse {
  microphone: VoiceMicrophoneAccess;
  speechRecognition: VoiceSpeechRecognitionAccess;
}

export type VoiceEventPayload =
  | { type: 'interim'; sessionId: string; text: string }
  | { type: 'final'; sessionId: string; text: string }
  | { type: 'stopped'; sessionId: string }
  | { type: 'error'; sessionId: string; message: string };

export interface VoiceApi {
  isSupported: () => Promise<VoiceIsSupportedResponse>;
  /**
   * Forget the cached probe result and re-run the helper. Used by the
   * Dictation settings tab when the user has enabled dictation or granted
   * permissions while Canopy was already running.
   */
  recheckSupported: () => Promise<VoiceIsSupportedResponse>;
  /**
   * Query the current macOS microphone privacy status. Returns
   * `'unavailable'` on non-macOS platforms or when the query fails.
   */
  getMicrophoneAccess: () => Promise<VoiceMicrophoneAccess>;
  /**
   * Prompt for Speech Recognition when macOS has not already made a decision,
   * and return the current microphone privacy status. Microphone prompts are
   * owned by the renderer getUserMedia path so macOS attributes the request to
   * the same app surface that captures audio.
   */
  requestSystemAccess: () => Promise<VoiceSystemAccessResponse>;
  start: (request: VoiceStartRequest) => Promise<VoiceStartResponse>;
  pushAudio: (request: VoicePushAudioRequest) => Promise<void>;
  stop: (request: VoiceStopRequest) => Promise<void>;
  cancel: (request: VoiceCancelRequest) => Promise<void>;
  onEvent: (cb: (event: VoiceEventPayload) => void) => () => void;
  /**
   * Opens a macOS System Settings pane via `x-apple.systempreferences:` URL.
   * Used by the error-recovery modal to deep-link to the right privacy or
   * keyboard pane.
   */
  openSettings: (request: VoiceOpenSettingsRequest) => Promise<void>;
}

