// ---------------------------------------------------------------------------
// App Advisor — shared identity, navigation, and IPC contract types
// ---------------------------------------------------------------------------

/**
 * Canonical declaration of the renderer's top-level navigation pages. Lives
 * in shared types so the App Advisor action union (which targets these
 * pages) does not duplicate the literal list. The renderer's
 * `navigationStore` re-exports this alias so renderer code keeps importing
 * from `@/stores/navigationStore`.
 *
 * Runtime behavior is unchanged — this is a string-literal type that the
 * navigation store consumes; it has no value at runtime.
 */
export type NavigationPage =
  | 'mcp-account-connections'
  | 'main'
  | 'overview'
  | 'home'
  | 'chat'
  /**
   * Legacy id of the retired cloud chat page (CAN-4185), kept so older
   * controllers and desktops still parse it. `navigate` opens the cowork
   * page, where cloud tasks open since CAN-6175 R2b.
   */
  | 'cloud-chat'
  | 'pipelines'
  | 'plugins'
  | 'audit'
  /**
   * Workflows → Runs, the Workflows landing page (CAN-3981). Schedule and
   * Library are its other two tabs.
   */
  | 'workflows'
  | 'workflows-schedule'
  | 'workflows-library'
  /**
   * Legacy Workflows ids from before CAN-3981, kept so stored links, App
   * Advisor and shortcuts still resolve. `navigate` never activates them:
   * `pipelines` and `automations` open Library filtered to their triggers and
   * `watchers` opens Runs filtered to watchers.
   */
  | 'automations'
  | 'watchers'
  | 'statistics'
  | 'usage'
  | 'environments'
  | 'workers'
  | 'kanban'
  /** The global Ledger Feed; reachable only while the Ledger is on. */
  | 'feed'
  /**
   * Dev-only Header States reference page, gated by
   * `header-states-page-flag.ts` (localStorage opt-in in dev, always on in
   * E2E, never in packaged builds).
   */
  | 'header-states'
  // Dev/E2E-only WorktreeRow state reference page. The page mounts in every
  // build (so navigation can never dead-end), but its sidebar entry is gated
  // to dev and E2E builds.
  | 'worktree-states'
  // Dev/E2E-only Activity card state-machine reference page.
  | 'activity-states'
  // Dev/E2E-only chat message-bubble state reference page. Same gating model
  // as 'worktree-states'.
  | 'message-bubble-states'
  // Dev/E2E-only review page for a batch of landed UI fixes, gated by
  // `change-review-page-flag.ts` (localStorage opt-in in dev, always on in
  // E2E, never in packaged builds).
  | 'change-review'
  // Dev/E2E-only reference page for every inline notice, gated by
  // `notice-states-page-flag.ts` (dev and E2E builds, never packaged).
  | 'notice-states';

/** Complete, stable runtime page vocabulary shared by schemas and discovery. */
export const NAVIGATION_PAGE_MAP: { readonly [Page in NavigationPage]: Page } =
  {
    main: 'main',
    overview: 'overview',
    home: 'home',
    chat: 'chat',
    'cloud-chat': 'cloud-chat',
    pipelines: 'pipelines',
    workflows: 'workflows',
    'workflows-schedule': 'workflows-schedule',
    'workflows-library': 'workflows-library',
    automations: 'automations',
    watchers: 'watchers',
    plugins: 'plugins',
    audit: 'audit',
    statistics: 'statistics',
    usage: 'usage',
    environments: 'environments',
    workers: 'workers',
    kanban: 'kanban',
    feed: 'feed',
    'header-states': 'header-states',
    'worktree-states': 'worktree-states',
    'activity-states': 'activity-states',
    'message-bubble-states': 'message-bubble-states',
    'change-review': 'change-review',
    'notice-states': 'notice-states',
    'mcp-account-connections': 'mcp-account-connections',
  };

