// ---------------------------------------------------------------------------
// Hook chat plugin dependency inspector (Phase T7)
// ---------------------------------------------------------------------------

export interface InspectHookChatPluginDependenciesRequest {
  projectId: string;
  worktreeId: string;
}

export interface HookChatPluginDependencyUsage {
  triggerName: string;
  scope: 'project' | 'workspace-root' | 'workspace-repo';
  repoId?: string;
  repoName?: string;
}

export interface HookChatPluginDependencyItem {
  key: string;
  kind: 'skill' | 'plugin';
  displayName: string;
  displayDescription: string;
  displaySource: string;
  installState: 'installable' | 'unavailable';
  installSpec?:
    | { kind: 'skill'; repo: string; skillName: string }
    | { kind: 'plugin'; repo: string; pluginName: string };
  usedBy: HookChatPluginDependencyUsage[];
}

export interface InspectHookChatPluginDependenciesResponse {
  items: HookChatPluginDependencyItem[];
}

// ---------------------------------------------------------------------------
// Recommended plugins inspector (canopy.json.plugins)
//
// The renderer surfaces source-controlled plugin recommendations from
// `canopy.json.plugins` and lets the user accept (install + select) or
// dismiss (opt-out) each one. The shapes below mirror the hook chat
// dependency inspector intentionally so the same install codepaths used by
// `HookChatPluginInstallDialog` can be reused. Keep `installSpec` in sync
// with `HookChatPluginDependencyItem.installSpec`.
// ---------------------------------------------------------------------------

/**
 * Discriminated union describing how a recommended plugin can be installed.
 * Mirrors {@link HookChatPluginDependencyItem.installSpec} so the renderer's
 * existing install dialog works for both surfaces.
 */
export type RecommendedPluginInstallSpec =
  | { kind: 'skill'; repo: string; skillName: string }
  | { kind: 'plugin'; repo: string; pluginName: string };

export interface RecommendedPluginItem {
  /** Canonical {@link getShareablePluginRefKey} string for the ref. */
  key: string;
  kind: 'skill' | 'plugin' | 'claude_plugin' | 'codex_plugin';
  displayName: string;
  displaySource: string;
  ref: ShareablePluginRef;
  /** True when the ref already resolves to an installed catalog entry. */
  installed: boolean;
  /** True when the ref is currently in the workspace default plugin selections. */
  selectedByDefault: boolean;
  /** True when the ref's key is present in `recommendedPluginOptOutKeys`. */
  optedOut: boolean;
  /**
   * Installability classification:
   * - `installed` covers builtin skills and matched catalog entries.
   * - `installable` requires github source (skill) or github marketplace (plugin).
   * - `unavailable` covers refs that cannot be auto-installed (e.g. unknown source).
   */
  installState: 'installed' | 'installable' | 'unavailable';
  /**
   * Suggested action for the renderer:
   * - `none`        — ref is already installed and selected by default.
   * - `select`      — ref is installed but not selected; only selection changes.
   * - `install-and-select` — ref is installable and not yet installed/selected.
   */
  action: 'none' | 'select' | 'install-and-select';
  /** Present when {@link installState} is `installable`. */
  installSpec?: RecommendedPluginInstallSpec;
  /** Present when {@link installState} is `unavailable`. */
  unavailableReason?: string;
}

export interface InspectRecommendedPluginsRequest {
  workspaceId: string;
  worktreeId: string;
  repoId?: string;
}

export interface InspectRecommendedPluginsResponse {
  workspaceId: string;
  worktreeId?: string;
  repoId?: string;
  scopeLabel: string;
  sourcePath?: string;
  /** All recommendations (installed, installable, opted-out, etc.). */
  items: RecommendedPluginItem[];
  /**
   * Subset of {@link items} that should drive the auto-prompt: not yet
   * installed/selected and not currently opted-out.
   */
  promptItems: RecommendedPluginItem[];
  /** Environment requirements declared alongside plugin recommendations. */
  requirements: PipelinePackageReadiness['requirements'];
}

export interface ApplyRecommendedPluginsRequest {
  workspaceId: string;
  worktreeId: string;
  repoId?: string;
  /**
   * Recommendations the user wants to install (if missing) and select by
   * default. These are also implicitly removed from opt-outs.
   */
  selectedKeys: string[];
  /** Recommendations to silence by adding to `recommendedPluginOptOutKeys`. */
  optOutKeys: string[];
  /**
   * Recommendations whose opt-out should be cleared without selecting them
   * (used by the settings panel `Suggest again` action). The apply service
   * removes only these keys from `recommendedPluginOptOutKeys`. Keys not in
   * any of the three arrays are left untouched.
   */
  clearOptOutKeys?: string[];
}

export interface RecommendedPluginApplyResult {
  key: string;
  status: 'selected' | 'installed-and-selected' | 'skipped' | 'error';
  message?: string;
}

export interface ApplyRecommendedPluginsResponse {
  workspaceId: string;
  worktreeId?: string;
  repoId?: string;
  results: RecommendedPluginApplyResult[];
  defaultPluginSelections: ChatTabPluginSelections;
  recommendedPluginOptOutKeys: string[];
}
import type {
  InstalledItemRef,
  InstalledItemStatus,
  InstalledItemUninstallTarget,
} from '@canopy/protocol/installed-items';
